/// Public and private witness values for the canonical Offline semantic circuit.
///
/// The first sixteen values are public instance columns. The private amount slots
/// let the circuit enforce bounded input/output counts and amount conservation
/// without exposing each individual note amount as a public instance.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OfflineNoteInstanceValues {
    /// Public instance values encoded as single-row Pasta field columns.
    pub public_values: [u64; OFFLINE_NOTE_INSTANCE_COLUMNS],
    /// Private input amount slots, normalized to a common decimal scale.
    pub input_amounts: [u64; OFFLINE_NOTE_MAX_INPUT_AMOUNTS],
    /// Private output amount slots, normalized to the same decimal scale.
    pub output_amounts: [u64; OFFLINE_NOTE_MAX_OUTPUT_AMOUNTS],
}

impl OfflineNoteInstanceValues {
    /// Return public instances in the byte layout carried by Halo2/STARK proof envelopes.
    #[must_use]
    pub fn public_instance_columns(&self) -> Vec<Vec<[u8; 32]>> {
        self.public_values
            .iter()
            .copied()
            .map(limb_as_instance_bytes)
            .map(|value| vec![value])
            .collect()
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn public_scalars(
        &self,
    ) -> [halo2_proofs::halo2curves::pasta::Fp; OFFLINE_NOTE_INSTANCE_COLUMNS] {
        self.public_values
            .map(halo2_proofs::halo2curves::pasta::Fp::from)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn input_amount_scalars(
        &self,
    ) -> [halo2_proofs::halo2curves::pasta::Fp; OFFLINE_NOTE_MAX_INPUT_AMOUNTS] {
        self.input_amounts
            .map(halo2_proofs::halo2curves::pasta::Fp::from)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn output_amount_scalars(
        &self,
    ) -> [halo2_proofs::halo2curves::pasta::Fp; OFFLINE_NOTE_MAX_OUTPUT_AMOUNTS] {
        self.output_amounts
            .map(halo2_proofs::halo2curves::pasta::Fp::from)
    }
}

/// Public witness values for the canonical Kagemusha folded semantic circuit.
///
/// The first four limbs bind the canonical folded-public-input hash, and the
/// remaining columns expose the aggregation mode and chain-visible
/// transcript fields that the proof envelope must match.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KagemushaFoldedInstanceValues {
    /// Public instance values encoded as single-row Pasta field columns.
    pub public_values: [u64; KAGEMUSHA_FOLDED_INSTANCE_COLUMNS],
}

impl KagemushaFoldedInstanceValues {
    /// Return public instances in the byte layout carried by Halo2 proof envelopes.
    #[must_use]
    pub fn public_instance_columns(&self) -> Vec<Vec<[u8; 32]>> {
        self.public_values
            .iter()
            .copied()
            .map(limb_as_instance_bytes)
            .map(|value| vec![value])
            .collect()
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn public_scalars(
        &self,
    ) -> [halo2_proofs::halo2curves::pasta::Fp; KAGEMUSHA_FOLDED_INSTANCE_COLUMNS] {
        self.public_values
            .map(halo2_proofs::halo2curves::pasta::Fp::from)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn hop_count_minus_one_bits(
        &self,
    ) -> Result<[halo2_proofs::halo2curves::pasta::Fp; KAGEMUSHA_FOLDED_HOP_COUNT_BITS], String>
    {
        let hop_count = self.public_values[KAGEMUSHA_FOLDED_HOP_COUNT_INDEX];
        if hop_count == 0
            || hop_count > iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS as u64
        {
            return Err(format!(
                "Kagemusha folded hop_count must be in 1..={}",
                iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS
            ));
        }
        let mut adjusted = hop_count - 1;
        Ok(std::array::from_fn(|_| {
            let bit = adjusted & 1;
            adjusted >>= 1;
            halo2_proofs::halo2curves::pasta::Fp::from(bit)
        }))
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn non_zero_public_field_inverses(
        &self,
    ) -> Result<
        [halo2_proofs::halo2curves::pasta::Fp; KAGEMUSHA_FOLDED_NON_ZERO_PUBLIC_FIELD_GROUP_COUNT],
        String,
    > {
        use ff::Field as _;

        let mut inverses = [halo2_proofs::halo2curves::pasta::Fp::from(0);
            KAGEMUSHA_FOLDED_NON_ZERO_PUBLIC_FIELD_GROUP_COUNT];
        for (group_index, group) in KAGEMUSHA_FOLDED_NON_ZERO_PUBLIC_FIELD_GROUPS
            .iter()
            .enumerate()
        {
            // Folded roots/digests are u64 limbs embedded in Pasta Fp; a four-limb
            // sum is zero exactly when every limb in the public field group is zero.
            let sum = group.iter().fold(
                halo2_proofs::halo2curves::pasta::Fp::from(0),
                |acc, index| {
                    acc + halo2_proofs::halo2curves::pasta::Fp::from(self.public_values[*index])
                },
            );
            inverses[group_index] = Option::from(sum.invert()).ok_or_else(|| {
                format!("Kagemusha folded public field group {group_index} must be non-zero")
            })?;
        }
        Ok(inverses)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn root_difference_witness(
        &self,
    ) -> Result<
        (
            [halo2_proofs::halo2curves::pasta::Fp; KAGEMUSHA_FOLDED_ROOT_LIMBS],
            halo2_proofs::halo2curves::pasta::Fp,
        ),
        String,
    > {
        use ff::Field as _;

        let mut selectors =
            [halo2_proofs::halo2curves::pasta::Fp::from(0); KAGEMUSHA_FOLDED_ROOT_LIMBS];
        for index in 0..KAGEMUSHA_FOLDED_ROOT_LIMBS {
            let initial = self.public_values[KAGEMUSHA_FOLDED_INITIAL_ROOT_START_INDEX + index];
            let final_root = self.public_values[KAGEMUSHA_FOLDED_FINAL_ROOT_START_INDEX + index];
            if initial != final_root {
                selectors[index] = halo2_proofs::halo2curves::pasta::Fp::from(1);
                let diff = halo2_proofs::halo2curves::pasta::Fp::from(final_root)
                    - halo2_proofs::halo2curves::pasta::Fp::from(initial);
                let inverse = Option::from(diff.invert()).expect("non-zero u64 limb difference");
                return Ok((selectors, inverse));
            }
        }
        Err("Kagemusha folded final root must differ from the initial root".to_owned())
    }
}

/// Public witness values for Kagemusha recursive aggregation proof envelopes.
///
/// The first four limbs bind the canonical recursive-proof public-input hash.
/// The remaining columns expose the recursive evidence digest, folded
/// public-input hash, aggregation transcript digest, Pallas parameter
/// fingerprint, fixed-window schedule and shared-table commitments, native
/// verifier-witness batch digest, recursive spend proof-chain digest,
/// transition-profile binding digest, append opening-preflight digest,
/// append-boundary digest, recursive verifier scalar-projection digest,
/// verifier opening length, witness count, and hop count that the proof
/// envelope must match.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct KagemushaRecursiveAggregationProofInstanceValues {
    /// Public instance values encoded as single-row Pasta field columns.
    pub public_values: [u64; KAGEMUSHA_RECURSIVE_AGGREGATION_PROOF_INSTANCE_COLUMNS],
}

impl KagemushaRecursiveAggregationProofInstanceValues {
    /// Return public instances in the byte layout carried by Halo2 proof envelopes.
    #[must_use]
    pub fn public_instance_columns(&self) -> Vec<Vec<[u8; 32]>> {
        self.public_values
            .iter()
            .copied()
            .map(limb_as_instance_bytes)
            .map(|value| vec![value])
            .collect()
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn public_scalars(
        &self,
    ) -> [halo2_proofs::halo2curves::pasta::Fp;
        KAGEMUSHA_RECURSIVE_AGGREGATION_PROOF_INSTANCE_COLUMNS] {
        self.public_values
            .map(halo2_proofs::halo2curves::pasta::Fp::from)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn opening_len_selectors(
        &self,
    ) -> Result<
        [halo2_proofs::halo2curves::pasta::Fp;
            KAGEMUSHA_RECURSIVE_AGGREGATION_OPENING_LEN_CHOICE_COUNT],
        String,
    > {
        let opening_len = self.public_values[KAGEMUSHA_RECURSIVE_AGGREGATION_OPENING_LEN_INDEX];
        let mut selectors = [halo2_proofs::halo2curves::pasta::Fp::from(0);
            KAGEMUSHA_RECURSIVE_AGGREGATION_OPENING_LEN_CHOICE_COUNT];
        let Some(index) = KAGEMUSHA_RECURSIVE_AGGREGATION_OPENING_LEN_CHOICES
            .iter()
            .position(|choice| *choice == opening_len)
        else {
            return Err(format!(
                "Kagemusha recursive aggregation opening length must be one of {:?} (found {opening_len})",
                KAGEMUSHA_RECURSIVE_AGGREGATION_OPENING_LEN_CHOICES
            ));
        };
        selectors[index] = halo2_proofs::halo2curves::pasta::Fp::from(1);
        Ok(selectors)
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn hop_count_minus_one_bits(
        &self,
    ) -> Result<
        [halo2_proofs::halo2curves::pasta::Fp; KAGEMUSHA_RECURSIVE_AGGREGATION_HOP_COUNT_BITS],
        String,
    > {
        let hop_count = self.public_values[KAGEMUSHA_RECURSIVE_AGGREGATION_HOP_COUNT_INDEX];
        if hop_count == 0
            || hop_count > iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS as u64
        {
            return Err(format!(
                "Kagemusha recursive aggregation hop_count must be in 1..={}",
                iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS
            ));
        }
        let mut adjusted = hop_count - 1;
        Ok(std::array::from_fn(|_| {
            let bit = adjusted & 1;
            adjusted >>= 1;
            halo2_proofs::halo2curves::pasta::Fp::from(bit)
        }))
    }

    #[cfg(feature = "zk-halo2-ipa")]
    fn non_zero_public_field_inverses(
        &self,
    ) -> Result<
        [halo2_proofs::halo2curves::pasta::Fp;
            KAGEMUSHA_RECURSIVE_AGGREGATION_NON_ZERO_PUBLIC_FIELD_GROUP_COUNT],
        String,
    > {
        use ff::Field as _;

        let mut inverses = [halo2_proofs::halo2curves::pasta::Fp::from(0);
            KAGEMUSHA_RECURSIVE_AGGREGATION_NON_ZERO_PUBLIC_FIELD_GROUP_COUNT];
        for (group_index, group) in KAGEMUSHA_RECURSIVE_AGGREGATION_NON_ZERO_PUBLIC_FIELD_GROUPS
            .iter()
            .enumerate()
        {
            let sum = group.iter().fold(
                halo2_proofs::halo2curves::pasta::Fp::from(0),
                |acc, index| {
                    acc + halo2_proofs::halo2curves::pasta::Fp::from(self.public_values[*index])
                },
            );
            inverses[group_index] = Option::from(sum.invert()).ok_or_else(|| {
                format!(
                    "Kagemusha recursive aggregation public field group {group_index} must be non-zero"
                )
            })?;
        }
        Ok(inverses)
    }
}

/// Build the canonical inline verifier key for Offline recursive note proofs.
///
/// The returned key is a real Halo2 IPA verifier key envelope (`IPAK` + `H2VK`)
/// for `offline-note-recursive`; it is suitable for WSV registration.
///
/// # Errors
///
/// Returns an error if Halo2 verifier-key generation fails.
#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
pub fn offline_note_recursive_vk_box() -> Result<VerifyingKeyBox, String> {
    static CACHE: std::sync::OnceLock<Result<VerifyingKeyBox, String>> = std::sync::OnceLock::new();

    CACHE
        .get_or_init(|| {
            build_offline_note_recursive_vk_box().map_err(|err| {
                format!("failed to generate offline-note-recursive verifying key: {err}")
            })
        })
        .clone()
}

pub(crate) fn ensure_offline_note_recursive_canonical_vk_box(
    vk_box: &VerifyingKeyBox,
) -> Result<(), String> {
    if vk_box.backend.as_str() != ZK_BACKEND_HALO2_IPA {
        return Err(format!(
            "Offline recursive verifier key backend `{}` is not `{ZK_BACKEND_HALO2_IPA}`",
            vk_box.backend
        ));
    }
    if vk_box.bytes.is_empty() {
        return Err("Offline recursive verifier key must be non-empty".to_owned());
    }
    #[cfg(feature = "zk-halo2-ipa")]
    {
        let canonical = offline_note_recursive_vk_box()?;
        if hash_vk(vk_box) != hash_vk(&canonical) || vk_box.bytes != canonical.bytes {
            return Err(
                "Offline recursive verifier key must match the canonical semantic circuit key"
                    .to_owned(),
            );
        }
    }
    Ok(())
}

#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
fn build_offline_note_recursive_vk_box() -> Result<VerifyingKeyBox, halo2_backend::Error> {
    let params = pasta_params_new(OFFLINE_NOTE_RECURSIVE_IPA_K);
    let circuit = pasta_tiny::OfflineNoteSemantic::default();
    let vk = halo2_backend::keygen_vk(&params, &circuit)?;
    let mut bytes = zk1::wrap_start();
    zk1::wrap_append_ipa_k(&mut bytes, OFFLINE_NOTE_RECURSIVE_IPA_K);
    zk1::wrap_append_circuit_id(&mut bytes, OFFLINE_NOTE_RECURSIVE_CIRCUIT_ID);
    zk1::wrap_append_vk_pasta(&mut bytes, &vk);
    Ok(VerifyingKeyBox::new(ZK_BACKEND_HALO2_IPA.to_owned(), bytes))
}

/// Build a governance/WSV verifier-key record for Offline recursive note proofs.
///
/// The record is active, embeds the real Halo2 IPA verifier key inline, and
/// binds to the canonical Offline public-input schema hash.
///
/// # Errors
///
/// Returns an error if verifier-key generation fails or the key length cannot be encoded.
#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
pub fn offline_note_recursive_vk_record(
    namespace: impl Into<String>,
    version: u32,
) -> Result<iroha_data_model::proof::VerifyingKeyRecord, String> {
    use iroha_data_model::{
        confidential::ConfidentialStatus,
        offline::offline_note_recursive_public_inputs_schema_hash, zk::BackendTag,
    };

    let vk_box = offline_note_recursive_vk_box()?;
    let mut record = iroha_data_model::proof::VerifyingKeyRecord::new(
        version,
        OFFLINE_NOTE_RECURSIVE_CIRCUIT_ID,
        BackendTag::Halo2IpaPasta,
        "pallas",
        offline_note_recursive_public_inputs_schema_hash(),
        hash_vk(&vk_box),
    );
    record.vk_len = u32::try_from(vk_box.bytes.len())
        .map_err(|_| "offline verifying key length overflowed u32".to_owned())?;
    record.max_proof_bytes = OFFLINE_NOTE_MAX_PROOF_BYTES;
    record.gas_schedule_id = Some("halo2_default".to_owned());
    record.key = Some(vk_box);
    record.status = ConfidentialStatus::Active;
    record.namespace = namespace.into();
    Ok(record)
}

