fn ensure_kagemusha_recursive_aggregation_canonical_vk_box(
    vk_box: &VerifyingKeyBox,
) -> Result<(), String> {
    ensure_kagemusha_recursive_semantic_vk_box_for_circuit(
        vk_box,
        KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
    )
}

fn ensure_kagemusha_recursive_semantic_vk_box_for_circuit(
    vk_box: &VerifyingKeyBox,
    expected_circuit_id: &str,
) -> Result<(), String> {
    if vk_box.backend != ZK_BACKEND_HALO2_IPA {
        return Err(format!(
            "Kagemusha recursive semantic verifier key backend `{}` is not `{ZK_BACKEND_HALO2_IPA}`",
            vk_box.backend
        ));
    }
    if vk_box.bytes.is_empty() {
        return Err("Kagemusha recursive semantic verifier key must be non-empty".to_owned());
    }
    #[cfg(feature = "zk-halo2-ipa")]
    {
        let canonical = match expected_circuit_id {
            KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID => {
                kagemusha_recursive_aggregation_proof_vk_box()?
            }
            KAGEMUSHA_RECURSIVE_COMPACT_CIRCUIT_ID => {
                kagemusha_recursive_compact_payment_token_vk_box()?
            }
            other => {
                return Err(format!(
                    "Kagemusha recursive semantic verifier key circuit id `{other}` is not supported"
                ));
            }
        };
        if hash_vk(vk_box) != hash_vk(&canonical) || vk_box.bytes != canonical.bytes {
            return Err(format!(
                "Kagemusha recursive semantic verifier key must match the canonical semantic circuit key `{expected_circuit_id}`"
            ));
        }
    }
    #[cfg(not(feature = "zk-halo2-ipa"))]
    if expected_circuit_id != KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID
        && expected_circuit_id != KAGEMUSHA_RECURSIVE_COMPACT_CIRCUIT_ID
    {
        return Err(format!(
            "Kagemusha recursive semantic verifier key circuit id `{expected_circuit_id}` is not supported"
        ));
    }
    Ok(())
}

/// Build a governance/WSV verifier-key record for Kagemusha recursive aggregation proofs.
///
/// The record is active, embeds the canonical transparent Halo2 IPA verifier key
/// inline, and binds to the recursive aggregation public-input schema. Compact
/// token mode `2` is admitted only by the ABI-7 recursive compact-token verifier,
/// not by the standalone recursive-aggregation verifier surface.
///
/// # Errors
///
/// Returns an error if verifier-key generation fails or the key length cannot be encoded.
#[cfg(feature = "zk-halo2-ipa")]
pub fn kagemusha_recursive_aggregation_proof_vk_record(
    namespace: impl Into<String>,
    version: u32,
) -> Result<iroha_data_model::proof::VerifyingKeyRecord, String> {
    let vk_box = kagemusha_recursive_aggregation_proof_vk_box()?;
    kagemusha_recursive_aggregation_proof_vk_record_from_box(namespace, version, vk_box)
}

fn hash_limb0(hash: &iroha_crypto::Hash) -> u64 {
    hash_to_u64_limbs_le(hash)[0]
}

fn hash_limb0_sum(hashes: &[iroha_crypto::Hash]) -> u64 {
    hashes
        .iter()
        .fold(0u64, |sum, hash| sum.wrapping_add(hash_limb0(hash)))
}

fn validate_offline_note_count(count: usize, max: usize, label: &str) -> Result<u64, String> {
    if count == 0 || count > max {
        return Err(format!("offline {label} count must be in 1..={max}"));
    }
    Ok(u64::try_from(count).expect("bounded offline count fits into u64"))
}

fn trimmed_numeric_scale(value: &iroha_primitives::Numeric) -> u32 {
    value.clone().trim_trailing_zeros().scale()
}

fn normalized_numeric_to_u64(value: &iroha_primitives::Numeric, target_scale: u32) -> Option<u64> {
    let value = value.clone().trim_trailing_zeros();
    if value.mantissa().is_negative() || value.scale() > target_scale {
        return None;
    }

    let scale_delta = target_scale - value.scale();
    let factor = iroha_primitives::BigInt::pow10(scale_delta)?;
    let scaled = value.mantissa().checked_mul(&factor).ok()?;
    scaled.to_string().parse::<u64>().ok()
}

fn normalized_amount_vec(amounts: &[&iroha_primitives::Numeric]) -> Result<Vec<u64>, String> {
    let target_scale = amounts
        .iter()
        .copied()
        .map(trimmed_numeric_scale)
        .max()
        .unwrap_or(0);
    amounts
        .iter()
        .copied()
        .map(|amount| {
            normalized_numeric_to_u64(amount, target_scale).ok_or_else(|| {
                "offline proof amount does not fit into u64 witness units".to_owned()
            })
        })
        .collect()
}

fn checked_u64_sum(values: &[u64], label: &str) -> Result<u64, String> {
    values.iter().try_fold(0u64, |sum, value| {
        sum.checked_add(*value)
            .ok_or_else(|| format!("offline {label} amount sum overflows u64 witness units"))
    })
}

fn offline_note_public_values(
    public_inputs_hash: &iroha_crypto::Hash,
    mode: u64,
    input_count: u64,
    output_count: u64,
    input_sum: u64,
    output_sum: u64,
    input_nullifier_sum: u64,
    output_commitment_sum: u64,
    key_certificate_payload_hash: &iroha_crypto::Hash,
    source_or_token: &iroha_crypto::Hash,
    input_claim_hash_sum: u64,
    output_claim_hash_sum: u64,
) -> [u64; OFFLINE_NOTE_INSTANCE_COLUMNS] {
    let hash_limbs = hash_to_u64_limbs_le(public_inputs_hash);
    [
        hash_limbs[0],
        hash_limbs[1],
        hash_limbs[2],
        hash_limbs[3],
        mode,
        input_count,
        output_count,
        input_sum,
        output_sum,
        input_nullifier_sum,
        output_commitment_sum,
        hash_limb0(key_certificate_payload_hash),
        hash_limb0(source_or_token),
        input_claim_hash_sum,
        output_claim_hash_sum,
        0,
    ]
}

/// Build the public/private instance values expected for an Offline redemption proof.
///
/// # Errors
///
/// Returns an error if the redemption shape is outside the circuit corridor, if
/// Norito hashing fails, or if normalized amounts do not fit in `u64` witness units.
pub fn offline_note_redeem_instance_values(
    redemption: &iroha_data_model::offline::OfflineNoteRedeem,
) -> Result<OfflineNoteInstanceValues, String> {
    use iroha_data_model::offline::OfflineNoteIssuedClaim;

    let input_count = validate_offline_note_count(
        redemption.input_nullifiers.len(),
        OFFLINE_NOTE_MAX_INPUT_AMOUNTS,
        "redemption input",
    )?;
    let output_count = 1;
    let public_inputs_hash = redemption
        .public_inputs_hash()
        .map_err(|err| format!("failed to encode Offline redemption public inputs: {err}"))?;
    let key_certificate_payload_hash = redemption
        .sender_key_certificate
        .payload_hash()
        .map_err(|err| format!("failed to encode Offline key certificate payload: {err}"))?;
    let issued_claim_hash = OfflineNoteIssuedClaim::from_redemption(redemption)
        .and_then(|claim| claim.claim_hash())
        .map_err(|err| format!("failed to encode Offline redemption issued claim: {err}"))?;

    let normalized_amounts = normalized_amount_vec(&[&redemption.amount, &redemption.amount])?;
    let input_sum = normalized_amounts[0];
    let output_sum = normalized_amounts[1];
    let public_values = offline_note_public_values(
        &public_inputs_hash,
        OFFLINE_NOTE_MODE_REDEEM,
        input_count,
        output_count,
        input_sum,
        output_sum,
        hash_limb0_sum(&redemption.input_nullifiers),
        0,
        &key_certificate_payload_hash,
        &redemption.source_note_commitment,
        hash_limb0(&issued_claim_hash),
        0,
    );

    let mut input_amounts = [0u64; OFFLINE_NOTE_MAX_INPUT_AMOUNTS];
    input_amounts[0] = input_sum;
    let mut output_amounts = [0u64; OFFLINE_NOTE_MAX_OUTPUT_AMOUNTS];
    output_amounts[0] = output_sum;

    Ok(OfflineNoteInstanceValues {
        public_values,
        input_amounts,
        output_amounts,
    })
}

/// Build the public/private instance values expected for an Offline audit proof.
///
/// # Errors
///
/// Returns an error if the audit shape is outside the circuit corridor, if Norito
/// hashing fails, if amounts do not fit in witness units, or if audited input and
/// output amounts are not conserved.
pub fn offline_note_audit_instance_values(
    audit: &iroha_data_model::offline::OfflineNoteAuditBundle,
) -> Result<OfflineNoteInstanceValues, String> {
    use iroha_data_model::offline::OfflineNoteIssuedClaim;

    let input_count = validate_offline_note_count(
        audit.input_claims.len(),
        OFFLINE_NOTE_MAX_INPUT_AMOUNTS,
        "audit input",
    )?;
    let output_count = validate_offline_note_count(
        audit.output_claims.len(),
        OFFLINE_NOTE_MAX_OUTPUT_AMOUNTS,
        "audit output",
    )?;
    if audit.input_nullifiers.len() != audit.input_claims.len() {
        return Err("offline audit input claim count must match input nullifier count".to_owned());
    }
    if audit.output_commitments.len() != audit.output_claims.len() {
        return Err(
            "offline audit output claim count must match output commitment count".to_owned(),
        );
    }
    if audit
        .output_commitments
        .iter()
        .zip(&audit.output_claims)
        .any(|(commitment, claim)| commitment != &claim.note_commitment)
    {
        return Err(
            "offline audit output claims must be ordered one-to-one with output commitments"
                .to_owned(),
        );
    }

    let public_inputs_hash = audit
        .public_inputs_hash()
        .map_err(|err| format!("failed to encode Offline audit public inputs: {err}"))?;
    let key_certificate_payload_hash = audit
        .sender_key_certificate
        .payload_hash()
        .map_err(|err| format!("failed to encode Offline key certificate payload: {err}"))?;
    for claim in &audit.input_claims {
        if claim.key_certificate_payload_hash != key_certificate_payload_hash {
            return Err("offline audit input claims must match sender key certificate".to_owned());
        }
    }
    if let Some(input_claim) = audit.input_claims.first() {
        let input_definition = input_claim.asset.definition();
        if audit
            .input_claims
            .iter()
            .any(|claim| claim.asset.definition() != input_definition)
            || audit
                .output_claims
                .iter()
                .any(|claim| claim.asset.definition() != input_definition)
        {
            return Err("offline audit input and output asset definitions must match".to_owned());
        }
    }

    let input_claim_hashes = audit
        .input_claims
        .iter()
        .map(|claim| {
            claim
                .claim_hash()
                .map_err(|err| format!("failed to encode Offline audit input claim: {err}"))
        })
        .collect::<Result<Vec<_>, _>>()?;
    let output_claim_hashes = audit
        .output_claims
        .iter()
        .map(|claim| {
            OfflineNoteIssuedClaim::from_audit_output(claim)
                .and_then(|claim| claim.claim_hash())
                .map_err(|err| format!("failed to encode Offline audit output claim: {err}"))
        })
        .collect::<Result<Vec<_>, _>>()?;

    let amount_refs = audit
        .input_claims
        .iter()
        .map(|claim| &claim.amount)
        .chain(audit.output_claims.iter().map(|claim| &claim.amount))
        .collect::<Vec<_>>();
    let normalized_amounts = normalized_amount_vec(&amount_refs)?;
    let input_len = audit.input_claims.len();
    let input_units = &normalized_amounts[..input_len];
    let output_units = &normalized_amounts[input_len..];
    let input_sum = checked_u64_sum(input_units, "input")?;
    let output_sum = checked_u64_sum(output_units, "output")?;
    if input_sum != output_sum {
        return Err("offline audit proof amounts are not conserved".to_owned());
    }

    let mut input_amounts = [0u64; OFFLINE_NOTE_MAX_INPUT_AMOUNTS];
    for (slot, amount) in input_amounts.iter_mut().zip(input_units.iter().copied()) {
        *slot = amount;
    }
    let mut output_amounts = [0u64; OFFLINE_NOTE_MAX_OUTPUT_AMOUNTS];
    for (slot, amount) in output_amounts.iter_mut().zip(output_units.iter().copied()) {
        *slot = amount;
    }

    let public_values = offline_note_public_values(
        &public_inputs_hash,
        OFFLINE_NOTE_MODE_AUDIT,
        input_count,
        output_count,
        input_sum,
        output_sum,
        hash_limb0_sum(&audit.input_nullifiers),
        hash_limb0_sum(&audit.output_commitments),
        &key_certificate_payload_hash,
        &audit.token_id,
        hash_limb0_sum(&input_claim_hashes),
        hash_limb0_sum(&output_claim_hashes),
    );

    Ok(OfflineNoteInstanceValues {
        public_values,
        input_amounts,
        output_amounts,
    })
}

/// Build the public instance values expected for a Kagemusha folded proof.
///
/// # Errors
///
/// Returns an error if the public input context is unsupported, if the payload
/// cannot be hashed, or if `hop_count` is outside the compact-token corridor.
pub fn kagemusha_folded_public_input_instance_values(
    public_inputs: &iroha_data_model::offline::KagemushaFoldedPublicInputs,
) -> Result<KagemushaFoldedInstanceValues, String> {
    public_inputs
        .validate_supported_context()
        .map_err(|err| err.to_string())?;
    let public_inputs_hash = public_inputs
        .public_inputs_hash()
        .map_err(|err| format!("failed to hash Kagemusha folded public inputs: {err}"))?;
    if public_inputs.hop_count == 0
        || usize::try_from(public_inputs.hop_count).map_or(true, |count| {
            count > iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS
        })
    {
        return Err(format!(
            "Kagemusha folded hop_count must be in 1..={}",
            iroha_data_model::offline::KAGEMUSHA_COMPACT_TOKEN_MAX_HOPS
        ));
    }

    let public_hash_limbs = hash_to_u64_limbs_le(&public_inputs_hash);
    let initial_root_limbs = bytes_to_u64_limbs_le(&public_inputs.initial_root);
    let final_root_limbs = bytes_to_u64_limbs_le(&public_inputs.final_root);
    let nullifier_limbs = hash_to_u64_limbs_le(&public_inputs.nullifier_digest);
    let output_limbs = hash_to_u64_limbs_le(&public_inputs.output_commitment_digest);
    let fold_limbs = hash_to_u64_limbs_le(&public_inputs.fold_digest);
    let aggregation_limbs = bytes_to_u64_limbs_le(&public_inputs.aggregation_transcript_digest);

    Ok(KagemushaFoldedInstanceValues {
        public_values: [
            public_hash_limbs[0],
            public_hash_limbs[1],
            public_hash_limbs[2],
            public_hash_limbs[3],
            u64::from(public_inputs.aggregation_mode),
            u64::from(public_inputs.hop_count),
            initial_root_limbs[0],
            initial_root_limbs[1],
            initial_root_limbs[2],
            initial_root_limbs[3],
            final_root_limbs[0],
            final_root_limbs[1],
            final_root_limbs[2],
            final_root_limbs[3],
            nullifier_limbs[0],
            nullifier_limbs[1],
            nullifier_limbs[2],
            nullifier_limbs[3],
            output_limbs[0],
            output_limbs[1],
            output_limbs[2],
            output_limbs[3],
            fold_limbs[0],
            fold_limbs[1],
            fold_limbs[2],
            fold_limbs[3],
            aggregation_limbs[0],
            aggregation_limbs[1],
            aggregation_limbs[2],
            aggregation_limbs[3],
        ],
    })
}

/// Build the public instance values expected for a recursive Kagemusha aggregation proof.
///
/// # Errors
///
/// Returns an error if the recursive proof public-input context is unsupported
/// or if the payload cannot be hashed.
pub fn kagemusha_recursive_aggregation_proof_public_input_instance_values(
    public_inputs: &iroha_data_model::offline::KagemushaRecursiveAggregationProofPublicInputs,
) -> Result<KagemushaRecursiveAggregationProofInstanceValues, String> {
    public_inputs
        .validate_context()
        .map_err(|err| err.to_string())?;
    let public_inputs_hash = public_inputs
        .public_inputs_hash()
        .map_err(|err| format!("failed to hash Kagemusha recursive proof public inputs: {err}"))?;
    let public_hash_limbs = hash_to_u64_limbs_le(&public_inputs_hash);
    let evidence_limbs = bytes_to_u64_limbs_le(&public_inputs.evidence_digest);
    let folded_hash_limbs = bytes_to_u64_limbs_le(&public_inputs.folded_public_inputs_hash);
    let aggregation_limbs = bytes_to_u64_limbs_le(&public_inputs.aggregation_transcript_digest);
    let params_limbs = bytes_to_u64_limbs_le(&public_inputs.verifier_params_fingerprint);
    let schedule_limbs = bytes_to_u64_limbs_le(&public_inputs.fixed_window_table_schedule_digest);
    let manifest_limbs =
        bytes_to_u64_limbs_le(&public_inputs.fixed_window_shared_table_manifest_digest);
    let table_base_limbs = bytes_to_u64_limbs_le(&public_inputs.fixed_window_table_base_digest);
    let batch_limbs = bytes_to_u64_limbs_le(&public_inputs.verifier_witness_batch_digest);
    let proof_chain_limbs = bytes_to_u64_limbs_le(&public_inputs.recursive_proof_chain_digest);
    let transition_profile_binding_limbs =
        bytes_to_u64_limbs_le(&public_inputs.transition_profile_binding_digest);
    let append_opening_preflight_limbs =
        bytes_to_u64_limbs_le(&public_inputs.append_opening_preflight_digest);
    let append_boundary_limbs = bytes_to_u64_limbs_le(&public_inputs.append_boundary_digest);
    let scalar_projection_limbs =
        bytes_to_u64_limbs_le(&public_inputs.recursive_verifier_scalar_projection_digest);

    Ok(KagemushaRecursiveAggregationProofInstanceValues {
        public_values: [
            public_hash_limbs[0],
            public_hash_limbs[1],
            public_hash_limbs[2],
            public_hash_limbs[3],
            evidence_limbs[0],
            evidence_limbs[1],
            evidence_limbs[2],
            evidence_limbs[3],
            folded_hash_limbs[0],
            folded_hash_limbs[1],
            folded_hash_limbs[2],
            folded_hash_limbs[3],
            aggregation_limbs[0],
            aggregation_limbs[1],
            aggregation_limbs[2],
            aggregation_limbs[3],
            params_limbs[0],
            params_limbs[1],
            params_limbs[2],
            params_limbs[3],
            schedule_limbs[0],
            schedule_limbs[1],
            schedule_limbs[2],
            schedule_limbs[3],
            manifest_limbs[0],
            manifest_limbs[1],
            manifest_limbs[2],
            manifest_limbs[3],
            table_base_limbs[0],
            table_base_limbs[1],
            table_base_limbs[2],
            table_base_limbs[3],
            batch_limbs[0],
            batch_limbs[1],
            batch_limbs[2],
            batch_limbs[3],
            proof_chain_limbs[0],
            proof_chain_limbs[1],
            proof_chain_limbs[2],
            proof_chain_limbs[3],
            transition_profile_binding_limbs[0],
            transition_profile_binding_limbs[1],
            transition_profile_binding_limbs[2],
            transition_profile_binding_limbs[3],
            append_opening_preflight_limbs[0],
            append_opening_preflight_limbs[1],
            append_opening_preflight_limbs[2],
            append_opening_preflight_limbs[3],
            append_boundary_limbs[0],
            append_boundary_limbs[1],
            append_boundary_limbs[2],
            append_boundary_limbs[3],
            scalar_projection_limbs[0],
            scalar_projection_limbs[1],
            scalar_projection_limbs[2],
            scalar_projection_limbs[3],
            u64::from(public_inputs.verifier_opening_len),
            u64::from(public_inputs.verifier_witness_count),
            u64::from(public_inputs.hop_count),
        ],
    })
}

/// Build the public instance values expected for a proof-carrying recursive aggregation bundle.
///
/// # Errors
///
/// Returns an error when the bundle is not canonically bound to its evidence or
/// when the instance layout cannot be built.
pub fn kagemusha_recursive_aggregation_proof_bundle_instance_values(
    bundle: &iroha_data_model::offline::KagemushaRecursiveAggregationProofBundle,
) -> Result<KagemushaRecursiveAggregationProofInstanceValues, String> {
    bundle
        .validate_evidence_binding()
        .map_err(|err| err.to_string())?;
    kagemusha_recursive_aggregation_proof_public_input_instance_values(
        &bundle.recursive_proof.public_inputs,
    )
}

/// Build the public instance values expected for a recursive Kagemusha spend bundle.
///
/// # Errors
///
/// Returns an error when the bundle is not canonically bound to its accumulator
/// or when the instance layout cannot be built.
pub fn kagemusha_recursive_spend_bundle_instance_values(
    bundle: &iroha_data_model::offline::KagemushaRecursiveSpendBundleV1,
) -> Result<KagemushaRecursiveAggregationProofInstanceValues, String> {
    bundle
        .validate_public_input_binding()
        .map_err(|err| err.to_string())?;
    kagemusha_recursive_aggregation_proof_public_input_instance_values(
        &bundle.recursive_proof.public_inputs,
    )
}

/// Build the public instance values expected for a compact Kagemusha token proof.
///
/// # Errors
///
/// Returns an error if the folded proof is not bound to the canonical public
/// inputs or if the instance layout cannot be built.
pub fn kagemusha_compact_token_instance_values(
    token: &iroha_data_model::offline::KagemushaCompactPaymentToken,
) -> Result<KagemushaFoldedInstanceValues, String> {
    token
        .validate_public_input_binding()
        .map_err(|err| err.to_string())?;
    kagemusha_folded_public_input_instance_values(&token.public_inputs)
}

fn hash_domain_separated_payload(domain: &[u8], backend: &str, bytes: &[u8]) -> [u8; 32] {
    let backend_len = u64::try_from(backend.len()).expect("backend length must fit into u64");
    let bytes_len = u64::try_from(bytes.len()).expect("payload length must fit into u64");
    let mut h = Sha256::new();
    h.update(domain);
    h.update(backend_len.to_be_bytes());
    h.update(backend.as_bytes());
    h.update(bytes_len.to_be_bytes());
    h.update(bytes);
    h.finalize().into()
}

/// Compute a stable, domain-separated 32-byte hash of the proof payload.
pub fn hash_proof(proof: &ProofBox) -> [u8; 32] {
    hash_domain_separated_payload(b"iroha:zk:v1:proof", &proof.backend, &proof.bytes)
}

/// Block-local key for cryptographically preverified proof results.
#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct PreverifiedProofKey {
    /// Domain-separated hash of the proof payload.
    pub proof_hash: [u8; 32],
    /// Registered verifying-key reference used for the verification result.
    pub vk_ref: VerifyingKeyId,
    /// Commitment of the registered verifying-key bytes used for verification.
    pub vk_commitment: [u8; 32],
}

impl PreverifiedProofKey {
    /// Build a preverified-result key from the proof payload and registered key binding.
    #[must_use]
    pub fn new(proof: &ProofBox, vk_ref: &VerifyingKeyId, vk_commitment: [u8; 32]) -> Self {
        Self {
            proof_hash: hash_proof(proof),
            vk_ref: vk_ref.clone(),
            vk_commitment,
        }
    }
}

/// Block-local preverified proof result map.
pub type PreverifiedProofMap = std::collections::BTreeMap<PreverifiedProofKey, bool>;

/// Compute a stable, domain-separated 32-byte hash of the verifying key payload.
pub fn hash_vk(vk: &VerifyingKeyBox) -> [u8; 32] {
    hash_vk_bytes(&vk.backend, &vk.bytes)
}

pub(crate) fn hash_vk_bytes(backend: &str, bytes: &[u8]) -> [u8; 32] {
    hash_domain_separated_payload(b"iroha:zk:v1:vk", backend, bytes)
}

/// Returns `true` when `backend` names an exact cataloged privacy protocol
/// family whose production verifier is not yet wired and audited.
#[inline]
#[must_use]
pub fn is_pending_production_backend_label(backend: &str) -> bool {
    iroha_data_model::zk::BackendTag::is_pending_production_backend_label(backend)
}

/// Returns `true` when `backend` denotes an explicitly admitted native
/// STARK/FRI verifier profile.
#[inline]
pub(crate) fn is_stark_fri_v1_backend(backend: &str) -> bool {
    backend == ZK_BACKEND_STARK_FRI_V1
        || backend
            .strip_prefix("stark/fri/")
            .is_some_and(|profile| STARK_FRI_V1_PRODUCTION_PROFILES.contains(&profile))
}

/// Returns `true` for backend labels that require a trusted setup and are not
/// admitted into the production verifier registry.
#[inline]
#[must_use]
pub fn is_trusted_setup_backend_label(backend: &str) -> bool {
    let backend = backend.to_ascii_lowercase();
    let backend = backend.as_str();
    has_trusted_setup_backend_segment(backend)
        || has_trusted_setup_backend_compact_label(backend)
        || backend == "groth16"
        || backend.starts_with("groth16/")
        || backend == "kzg"
        || backend.starts_with("kzg/")
        || backend == "bn254"
        || backend == "bn256"
        || backend == "bls12_381"
        || backend == "bls12-381"
        || backend == "halo2/bn254"
        || backend.starts_with("halo2/bn254/")
        || backend.contains("/bn254")
        || backend.contains(":bn254")
        || backend.contains("/bn256")
        || backend.contains(":bn256")
        || backend.contains("/bls12")
        || backend.contains(":bls12")
        || backend == "halo2/kzg"
        || backend.starts_with("halo2/kzg/")
        || backend.contains("/kzg")
        || backend.contains(":kzg")
}

fn has_trusted_setup_backend_segment(backend: &str) -> bool {
    const TRUSTED_SETUP_SEGMENTS: &[&str] = &[
        "groth16",
        "kzg",
        "bn254",
        "bn256",
        "bls12",
        "srs",
        "crs",
        "ptau",
        "ceremony",
        "powersoftau",
    ];
    backend
        .split(|ch: char| !ch.is_ascii_alphanumeric())
        .any(|segment| TRUSTED_SETUP_SEGMENTS.contains(&segment))
}

fn has_trusted_setup_backend_compact_label(backend: &str) -> bool {
    let compact = backend
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .collect::<String>();
    [
        "groth16",
        "kzg",
        "bn254",
        "bn256",
        "bls12381",
        "bls12",
        "srs",
        "crs",
        "ptau",
        "ceremony",
        "trustedsetup",
        "structuredreferencestring",
        "universalsrs",
        "powersoftau",
    ]
    .iter()
    .any(|token| compact.contains(token))
}

const DEVELOPER_ONLY_EMBEDDED_BACKEND_TOKENS: &[&str] = &["debug", "mock", "fixture", "dev"];
const DEVELOPER_ONLY_EXACT_BACKEND_TOKENS: &[&str] =
    &["test", "dummy", "fake", "stub", "sample", "placeholder"];
const PRODUCTION_CLAIM_BACKEND_FRAGMENTS: &[&str] = &[
    "productionready",
    "productionhardened",
    "productionenabled",
    "productionapproved",
    "productioncertified",
    "productionclaim",
    "claimedproduction",
    "mainnetready",
    "mainnetcomplete",
    "mainnetclaim",
    "claimedmainnet",
    "mainnetcertified",
    "mainnetapproved",
    "mainnetrelease",
    "auditedproduction",
    "externallyaudited",
    "thirdpartyaudited",
    "boiaudited",
    "auditedmainnet",
    "externalaudit",
    "auditpassed",
    "auditapproved",
    "auditsignoff",
    "auditclaim",
    "claimedaudit",
    "securityreviewpassed",
    "securityauditpassed",
    "securityaudited",
    "externalsecurityreview",
    "certifiedproduction",
    "certifiedmainnet",
    "releaseready",
    "releaseapproved",
    "releasecertified",
];

fn compact_ascii_lowercase_label(value: &str) -> String {
    value
        .chars()
        .filter(|ch| ch.is_ascii_alphanumeric())
        .map(|ch| ch.to_ascii_lowercase())
        .collect()
}

#[inline]
fn is_developer_only_direct_backend_token(token: &str) -> bool {
    DEVELOPER_ONLY_EMBEDDED_BACKEND_TOKENS
        .iter()
        .any(|reserved| token.contains(reserved))
        || DEVELOPER_ONLY_EXACT_BACKEND_TOKENS.contains(&token)
}

#[inline]
fn is_developer_only_compact_backend_run(run: &str) -> bool {
    DEVELOPER_ONLY_EMBEDDED_BACKEND_TOKENS
        .iter()
        .any(|reserved| run.contains(reserved))
        || DEVELOPER_ONLY_EXACT_BACKEND_TOKENS.contains(&run)
}

/// Returns `true` for developer-only backend labels that must not enter
/// production proof admission, preverification, or verifier dispatch.
#[inline]
#[must_use]
pub fn is_developer_only_backend_label(backend: &str) -> bool {
    let backend = backend.to_ascii_lowercase();
    let mut letter_run = String::new();
    for token in backend
        .split(|ch: char| !ch.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
    {
        if is_developer_only_direct_backend_token(token) {
            return true;
        }
        if token.len() == 1 {
            letter_run.push_str(token);
        } else {
            if is_developer_only_compact_backend_run(&letter_run) {
                return true;
            }
            letter_run.clear();
        }
    }
    is_developer_only_compact_backend_run(&letter_run)
}

/// Returns `true` for verifier backend labels that claim production, mainnet,
/// or audit readiness instead of matching an explicitly admitted verifier id.
#[inline]
#[must_use]
pub fn is_production_claim_backend_label(backend: &str) -> bool {
    let compact = compact_ascii_lowercase_label(backend);
    PRODUCTION_CLAIM_BACKEND_FRAGMENTS
        .iter()
        .any(|fragment| compact.contains(fragment))
}

/// Returns `true` when `backend` is accepted for `ivm-execution-v1` proofs.
#[inline]
#[must_use]
pub fn is_ivm_execution_backend(backend: &str) -> bool {
    backend == ZK_BACKEND_HALO2_IPA || is_stark_fri_v1_backend(backend)
}

/// Return the expected OpenVerify backend tag for labels admitted by native
/// production verifier dispatch.
#[must_use]
pub fn production_verify_backend_tag(backend: &str) -> Option<iroha_data_model::zk::BackendTag> {
    if !production_verify_backend_label_is_portable(backend)
        || is_pending_production_backend_label(backend)
        || is_production_claim_backend_label(backend)
        || is_trusted_setup_backend_label(backend)
        || is_developer_only_backend_label(backend)
    {
        return None;
    }

    if is_stark_fri_v1_backend(backend) {
        return Some(iroha_data_model::zk::BackendTag::Stark);
    }
    if backend == ZK_BACKEND_HALO2_IPA
        || verifier_registry_accepts_backend(backend)
        || is_native_halo2_pasta_backend_label(backend)
    {
        return Some(iroha_data_model::zk::BackendTag::Halo2IpaPasta);
    }
    None
}

fn production_verify_backend_label_is_portable(backend: &str) -> bool {
    if backend.is_empty() || backend.trim() != backend {
        return false;
    }
    let Some(first) = backend.as_bytes().first() else {
        return false;
    };
    let Some(last) = backend.as_bytes().last() else {
        return false;
    };
    if !first.is_ascii_alphanumeric() || !last.is_ascii_alphanumeric() {
        return false;
    }
    if backend.as_bytes().iter().any(|&byte| {
        !matches!(
            byte,
            b'a'..=b'z' | b'0'..=b'9' | b'/' | b':' | b'-' | b'_' | b'.'
        )
    }) {
        return false;
    }
    !["//", "::", "..", "/:", ":/", "/.", "./", ":.", ".:"]
        .iter()
        .any(|separator| backend.contains(separator))
}

/// Returns `true` when `backend` names a verifier family that can reach native
/// production verifier dispatch.
#[inline]
#[must_use]
pub fn is_production_verify_backend_label(backend: &str) -> bool {
    production_verify_backend_tag(backend).is_some()
}

fn is_native_halo2_pasta_backend_label(backend: &str) -> bool {
    let Some(normalized) = normalize_native_halo2_pasta_backend_label(backend) else {
        return false;
    };
    // Native dispatch still contains developer fixtures for local proof tests;
    // production backend admission must never advertise those circuit ids.
    let profile = normalized.rsplit('/').next().unwrap_or("");
    !profile.starts_with("tiny-")
        && !is_developer_only_backend_label(&normalized)
        && !is_legacy_vote_bool_backend_profile(profile)
        && !is_legacy_anon_transfer_backend_profile(profile)
        && is_native_halo2_pasta_circuit_id(&normalized)
}

fn is_legacy_vote_bool_backend_profile(profile: &str) -> bool {
    matches!(
        profile,
        "vote-bool-commit"
            | "vote-bool-commit-merkle2"
            | "vote-bool-commit-merkle8"
            | "vote-bool-commit-merkle16"
    )
}

fn is_legacy_anon_transfer_backend_profile(profile: &str) -> bool {
    matches!(
        profile,
        "anon-transfer-2x2"
            | "anon-transfer-2x2-merkle2"
            | "anon-transfer-2x2-merkle8"
            | "anon-transfer-2x2-merkle16"
    )
}

fn normalize_native_halo2_pasta_backend_label(backend: &str) -> Option<String> {
    if backend.is_empty() || backend.trim() != backend {
        return None;
    }
    if let Some(rest) = backend.strip_prefix("halo2/pasta/ipa/") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/{rest}"));
    }
    if let Some(rest) = backend.strip_prefix("halo2/pasta/") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/{rest}"));
    }
    if let Some(rest) = backend.strip_prefix("halo2/ipa::") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/{rest}"));
    }
    if let Some(rest) = backend.strip_prefix("halo2/ipa:") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/{rest}"));
    }
    if let Some(rest) = backend.strip_prefix("halo2/ipa/") {
        return (!rest.is_empty()).then(|| format!("halo2/pasta/{rest}"));
    }
    None
}

fn is_native_halo2_pasta_circuit_id(circuit_id: &str) -> bool {
    matches!(
        circuit_id,
        "halo2/pasta/tiny-add"
            | "halo2/pasta/tiny-mul"
            | "halo2/pasta/tiny-add-2rows"
            | "halo2/pasta/tiny-add-public"
            | "halo2/pasta/tiny-mul-public"
            | "halo2/pasta/tiny-id-public"
            | "halo2/pasta/tiny-add3"
            | "halo2/pasta/tiny-add2inst-public"
            | "halo2/pasta/asset-hidden-transfer-public-test"
            | "halo2/pasta/tiny-anon-transfer-2x2"
            | "halo2/pasta/kaigi-roster-v1"
            | "halo2/pasta/kaigi-usage-v1"
            | "halo2/pasta/tiny-vote-bool"
            | "halo2/pasta/ivm-overlay-bind"
            | "halo2/pasta/ivm-execution-v1"
            | "halo2/pasta/offline-note-recursive"
            | "halo2/pasta/kagemusha-folded-v1"
            | "halo2/pasta/kagemusha-recursive-aggregation-v1"
            | "halo2/pasta/kagemusha-recursive-compact-v1"
            | "halo2/pasta/kagemusha-recursive-spend-lineage-v1"
            | "halo2/pasta/kagemusha-recursive-spend-lineage-onehop-v1"
            | "halo2/pasta/kagemusha-recursive-spend-lineage-append-v1"
            | "halo2/pasta/tiny-commit-open"
            | "halo2/pasta/tiny-merkle2"
            | "halo2/pasta/vote-bool-commit"
            | "halo2/pasta/vote-bool-commit-merkle2"
            | "halo2/pasta/vote-bool-commit-merkle8"
            | "halo2/pasta/vote-bool-commit-merkle16"
            | "halo2/pasta/anon-transfer-2x2"
            | "halo2/pasta/anon-transfer-2x2-merkle2"
            | "halo2/pasta/anon-transfer-2x2-merkle8"
            | "halo2/pasta/anon-transfer-2x2-merkle16"
    ) || {
        #[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
        {
            confidential_v2::is_confidential_transfer_v2_circuit_id(circuit_id)
                || confidential_v2::is_confidential_unshield_v2_circuit_id(circuit_id)
                || confidential_v2::is_confidential_unshield_v3_circuit_id(circuit_id)
        }
        #[cfg(not(any(feature = "zk-halo2", feature = "zk-halo2-ipa")))]
        {
            let _ = circuit_id;
            false
        }
    }
}

fn hash_to_u64_limbs_le(hash: &iroha_crypto::Hash) -> [u64; 4] {
    let bytes: &[u8; 32] = hash.as_ref();
    bytes_to_u64_limbs_le(bytes)
}

fn bytes_to_u64_limbs_le(bytes: &[u8; 32]) -> [u64; 4] {
    let mut limbs = [0u64; 4];
    for (idx, limb) in limbs.iter_mut().enumerate() {
        let start = idx * 8;
        let end = start + 8;
        *limb = u64::from_le_bytes(bytes[start..end].try_into().expect("8-byte limb"));
    }
    limbs
}

fn limb_as_instance_bytes(limb: u64) -> [u8; 32] {
    let mut out = [0u8; 32];
    out[..8].copy_from_slice(&limb.to_le_bytes());
    out
}

#[cfg(feature = "zk-stark")]
fn ivm_execution_public_inputs_columns(
    code_hash: iroha_crypto::Hash,
    overlay_hash: iroha_crypto::Hash,
    events_commitment: iroha_crypto::Hash,
    gas_policy_commitment: iroha_crypto::Hash,
) -> Vec<Vec<[u8; 32]>> {
    let code_limbs = hash_to_u64_limbs_le(&code_hash);
    let overlay_limbs = hash_to_u64_limbs_le(&overlay_hash);
    let events_limbs = hash_to_u64_limbs_le(&events_commitment);
    let gas_limbs = hash_to_u64_limbs_le(&gas_policy_commitment);
    code_limbs
        .into_iter()
        .chain(overlay_limbs)
        .chain(events_limbs)
        .chain(gas_limbs)
        .map(limb_as_instance_bytes)
        .map(|value| vec![value])
        .collect()
}

#[cfg(feature = "zk-halo2-ipa")]
fn ensure_halo2_ipa_proving_key_compatible(
    proving_key: &halo2_backend::ProvingKey,
    parsed_vk: &halo2_backend::VerifyingKey,
    params: &PastaParams,
    domain_message: &str,
    vk_message: &str,
) -> Result<(), String> {
    if halo2_backend::proving_key_domain_k(proving_key) != params.k() {
        return Err(domain_message.to_owned());
    }
    if halo2_backend::proving_key_vk_to_processed_bytes(proving_key)
        != halo2_backend::verifying_key_to_processed_bytes(parsed_vk)
    {
        return Err(vk_message.to_owned());
    }
    Ok(())
}

#[cfg(feature = "zk-halo2-ipa")]
fn create_halo2_ipa_proof<C>(
    params: &PastaParams,
    proving_key: &halo2_backend::ProvingKey,
    circuit: C,
    instance_refs: &[&[&[halo2_backend::Scalar]]],
    context: &str,
) -> Result<Vec<u8>, String>
where
    C: halo2_proofs::plonk::Circuit<halo2_backend::Scalar>,
{
    halo2_backend::create_ipa_proof(params, proving_key, &[circuit], instance_refs)
        .map_err(|err| format!("failed to create {context} proof: {err}"))
}

#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
fn verify_halo2_ipa_payload_no_instances(
    params: &PastaParams,
    vk: &halo2_backend::VerifyingKey,
    proof_payload: &[u8],
) -> bool {
    halo2_backend::verify_ipa_proof_no_instances(params, vk, proof_payload).is_ok()
}

#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
fn verify_halo2_ipa_payload_columns_result(
    params: &PastaParams,
    vk: &halo2_backend::VerifyingKey,
    proof_payload: &[u8],
    col_refs: &[&[halo2_backend::Scalar]],
) -> Result<(), halo2_backend::Error> {
    halo2_backend::verify_ipa_proof_with_columns(params, vk, proof_payload, col_refs)
}

#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
fn verify_halo2_ipa_payload_columns(
    params: &PastaParams,
    vk: &halo2_backend::VerifyingKey,
    proof_payload: &[u8],
    col_refs: &[&[halo2_backend::Scalar]],
) -> bool {
    verify_halo2_ipa_payload_columns_result(params, vk, proof_payload, col_refs).is_ok()
}

#[cfg(any(feature = "zk-halo2", feature = "zk-halo2-ipa"))]
fn verify_halo2_ipa_payload_optional_columns(
    params: &PastaParams,
    vk: &halo2_backend::VerifyingKey,
    proof_payload: &[u8],
    col_refs: &[&[halo2_backend::Scalar]],
) -> bool {
    if col_refs.is_empty() {
        verify_halo2_ipa_payload_no_instances(params, vk, proof_payload)
    } else {
        verify_halo2_ipa_payload_columns(params, vk, proof_payload, col_refs)
    }
}

/// Build a Halo2 IPA `ivm-execution-v1` proof envelope for IVM proved execution.
///
/// The produced proof binds these public commitments:
/// `(code_hash, overlay_hash, events_commitment, gas_policy_commitment)`.
///
/// Note: the current `ivm-execution-v1` circuit is a **binding** circuit. It does **not**
/// prove correct IVM execution semantics by itself, so admission still performs deterministic
/// VM replay to recompute the overlay/commitments and reject mismatches.
///
/// If `proving_key_bytes` is provided, it is used as the proving key after strict
/// compatibility checks against `vk_box`. If omitted, the proving key is derived
/// from `vk_box` and the canonical `IvmExecutionBindV1` circuit.
#[cfg(feature = "zk-halo2-ipa")]
pub fn prove_halo2_ipa_ivm_execution_envelope(
    circuit_id: &str,
    vk_box: &VerifyingKeyBox,
    code_hash: iroha_crypto::Hash,
    overlay_hash: iroha_crypto::Hash,
    events_commitment: iroha_crypto::Hash,
    gas_policy_commitment: iroha_crypto::Hash,
    proving_key_bytes: Option<&[u8]>,
) -> Result<ProofBox, String> {
    use std::io::Cursor;

    use halo2_backend::Scalar;
    use iroha_data_model::zk::{BackendTag, OpenVerifyEnvelope};
    if !is_ivm_execution_v1_circuit_id(circuit_id) {
        return Err(format!(
            "unsupported IVM execution circuit id `{circuit_id}`"
        ));
    }
    if vk_box.backend.as_str() != ZK_BACKEND_HALO2_IPA {
        return Err("ivm execution proving requires halo2/ipa verifying key backend".to_owned());
    }

    let params = zkparse::params_any(vk_box.bytes.as_slice())
        .ok_or_else(|| "missing/invalid IPAK parameters in verifying key envelope".to_owned())?;
    let parsed_vk: halo2_backend::VerifyingKey = zkparse::vk_from_bytes::<
        pasta_tiny::IvmExecutionBindV1,
    >(vk_box.bytes.as_slice(), &params)
    .ok_or_else(|| "missing/invalid H2VK payload for ivm-execution-v1 verifying key".to_owned())?;

    let code_limbs = hash_to_u64_limbs_le(&code_hash);
    let overlay_limbs = hash_to_u64_limbs_le(&overlay_hash);
    let events_limbs = hash_to_u64_limbs_le(&events_commitment);
    let gas_limbs = hash_to_u64_limbs_le(&gas_policy_commitment);

    let values: [Scalar; 16] = [
        Scalar::from(code_limbs[0]),
        Scalar::from(code_limbs[1]),
        Scalar::from(code_limbs[2]),
        Scalar::from(code_limbs[3]),
        Scalar::from(overlay_limbs[0]),
        Scalar::from(overlay_limbs[1]),
        Scalar::from(overlay_limbs[2]),
        Scalar::from(overlay_limbs[3]),
        Scalar::from(events_limbs[0]),
        Scalar::from(events_limbs[1]),
        Scalar::from(events_limbs[2]),
        Scalar::from(events_limbs[3]),
        Scalar::from(gas_limbs[0]),
        Scalar::from(gas_limbs[1]),
        Scalar::from(gas_limbs[2]),
        Scalar::from(gas_limbs[3]),
    ];

    let instance_columns_owned: Vec<Vec<Scalar>> =
        values.iter().map(|value| vec![*value]).collect();
    let instance_columns: Vec<&[Scalar]> =
        instance_columns_owned.iter().map(Vec::as_slice).collect();
    let instance_refs: Vec<&[&[Scalar]]> = vec![instance_columns.as_slice()];

    let vk_commitment = hash_vk(vk_box);
    let proving_key: halo2_backend::ProvingKey = if let Some(bytes) = proving_key_bytes {
        let proving_key_raw = decode_halo2_ipa_proving_key_archive(
            bytes,
            IVM_EXECUTION_V1_CIRCUIT_ID,
            vk_commitment,
        )?;
        let mut cursor = Cursor::new(proving_key_raw.as_slice());
        let pk = read_proving_key::<pasta_tiny::IvmExecutionBindV1, _>(&mut cursor)
            .map_err(|err| format!("failed to decode proving key: {err}"))?;
        let consumed = usize::try_from(cursor.position()).unwrap_or(usize::MAX);
        if consumed != proving_key_raw.len() {
            return Err("failed to decode proving key: trailing bytes".to_owned());
        }
        ensure_halo2_ipa_proving_key_compatible(
            &pk,
            &parsed_vk,
            &params,
            "proving key domain does not match IPAK parameters",
            "proving key verifying key does not match vk_ref bytes",
        )?;
        pk
    } else {
        halo2_backend::keygen_pk(
            &params,
            parsed_vk.clone(),
            &pasta_tiny::IvmExecutionBindV1::default(),
        )
        .map_err(|err| format!("failed to derive proving key: {err}"))?
    };

    let circuit = pasta_tiny::IvmExecutionBindV1 { values };
    let proof_raw = create_halo2_ipa_proof(
        &params,
        &proving_key,
        circuit,
        &instance_refs,
        "ivm-execution-v1",
    )?;

    let mut proof_payload = zk1::wrap_start();
    zk1::wrap_append_proof(&mut proof_payload, &proof_raw);
    zk1::wrap_append_instances_pasta_fp_cols(instance_columns.as_slice(), &mut proof_payload);

    let public_inputs = ivm_execution_public_inputs_schema_descriptor().to_vec();
    let envelope = OpenVerifyEnvelope {
        backend: BackendTag::Halo2IpaPasta,
        circuit_id: circuit_id.to_owned(),
        vk_hash: vk_commitment,
        public_inputs,
        proof_bytes: proof_payload,
        aux: Vec::new(),
    };
    let encoded = norito::to_bytes(&envelope)
        .map_err(|err| format!("failed to encode OpenVerifyEnvelope: {err}"))?;
    Ok(ProofBox::new(ZK_BACKEND_HALO2_IPA.to_owned(), encoded))
}

/// Derive Halo2 IPA proving-key bytes for the canonical `ivm-execution-v1` circuit.
///
/// The returned bytes are a Norito archive containing the Halo2 `ProvingKey`
/// serialization, canonical circuit family, and verifier-key commitment,
/// suitable for persistence in the Torii prover key store (`<backend>__<name>.pk`).
///
/// Note: this operation is expensive (key generation) and should be performed offline.
#[cfg(feature = "zk-halo2-ipa")]
pub fn derive_halo2_ipa_ivm_execution_proving_key_bytes(
    vk_box: &VerifyingKeyBox,
) -> Result<Vec<u8>, String> {
    if vk_box.backend.as_str() != ZK_BACKEND_HALO2_IPA {
        return Err(
            "ivm execution proving key derivation requires halo2/ipa verifying key backend"
                .to_owned(),
        );
    }

    let params = zkparse::params_any(vk_box.bytes.as_slice())
        .ok_or_else(|| "missing/invalid IPAK parameters in verifying key envelope".to_owned())?;
    let parsed_vk: halo2_backend::VerifyingKey = zkparse::vk_from_bytes::<
        pasta_tiny::IvmExecutionBindV1,
    >(vk_box.bytes.as_slice(), &params)
    .ok_or_else(|| "missing/invalid H2VK payload for ivm-execution-v1 verifying key".to_owned())?;

    let pk = halo2_backend::keygen_pk(
        &params,
        parsed_vk,
        &pasta_tiny::IvmExecutionBindV1::default(),
    )
    .map_err(|err| format!("failed to derive proving key: {err}"))?;
    encode_halo2_ipa_proving_key_archive(
        IVM_EXECUTION_V1_CIRCUIT_ID,
        hash_vk(vk_box),
        halo2_backend::proving_key_to_processed_bytes(&pk),
    )
}

#[cfg(feature = "zk-halo2-ipa")]
fn cached_offline_note_proving_key(
    params: &PastaParams,
    parsed_vk: &halo2_backend::VerifyingKey,
    vk_commitment: [u8; 32],
) -> Result<Arc<halo2_backend::ProvingKey>, String> {
    static CACHE: OnceLock<Mutex<BTreeMap<[u8; 32], Arc<halo2_backend::ProvingKey>>>> =
        OnceLock::new();

    let cache = CACHE.get_or_init(|| Mutex::new(BTreeMap::new()));
    if let Some(proving_key) = cache
        .lock()
        .expect("offline note proving key cache mutex poisoned")
        .get(&vk_commitment)
        .cloned()
    {
        return Ok(proving_key);
    }

    let proving_key = halo2_backend::keygen_pk(
        params,
        parsed_vk.clone(),
        &pasta_tiny::OfflineNoteSemantic::default(),
    )
    .map_err(|err| format!("failed to derive proving key: {err}"))?;
    let proving_key = Arc::new(proving_key);
    let mut cache = cache
        .lock()
        .expect("offline note proving key cache mutex poisoned");
    match cache.entry(vk_commitment) {
        Entry::Occupied(entry) => Ok(Arc::clone(entry.get())),
        Entry::Vacant(entry) => Ok(Arc::clone(entry.insert(proving_key))),
    }
}

#[cfg(feature = "zk-halo2-ipa")]
fn prove_halo2_ipa_offline_note_envelope(
    circuit_id: &str,
    vk_box: &VerifyingKeyBox,
    instance_values: OfflineNoteInstanceValues,
    proving_key_bytes: Option<&[u8]>,
) -> Result<ProofBox, String> {
    use std::io::Cursor;

    use halo2_backend::Scalar;
    use iroha_data_model::{
        offline::OFFLINE_NOTE_RECURSIVE_PUBLIC_INPUTS_SCHEMA,
        zk::{BackendTag, OpenVerifyEnvelope},
    };
    if circuit_id != OFFLINE_NOTE_RECURSIVE_CIRCUIT_ID {
        return Err(format!(
            "Offline recursive proving requires canonical circuit id `{OFFLINE_NOTE_RECURSIVE_CIRCUIT_ID}` (found `{circuit_id}`)"
        ));
    }
    ensure_offline_note_recursive_canonical_vk_box(vk_box)?;

    let params = zkparse::params_any(vk_box.bytes.as_slice())
        .ok_or_else(|| "missing/invalid IPAK parameters in verifying key envelope".to_owned())?;
    let parsed_vk: halo2_backend::VerifyingKey =
        zkparse::vk_from_bytes::<pasta_tiny::OfflineNoteSemantic>(vk_box.bytes.as_slice(), &params)
            .ok_or_else(|| {
                "missing/invalid H2VK payload for offline-note-recursive verifying key".to_owned()
            })?;

    let public_values = instance_values.public_scalars();
    let instance_columns_owned: Vec<Vec<Scalar>> =
        public_values.iter().map(|value| vec![*value]).collect();
    let instance_columns: Vec<&[Scalar]> =
        instance_columns_owned.iter().map(Vec::as_slice).collect();
    let instance_refs: Vec<&[&[Scalar]]> = vec![instance_columns.as_slice()];

    let vk_commitment = hash_vk(vk_box);
    let proving_key: Arc<halo2_backend::ProvingKey> = if let Some(bytes) = proving_key_bytes {
        let proving_key_raw = decode_halo2_ipa_proving_key_archive(
            bytes,
            OFFLINE_NOTE_RECURSIVE_CIRCUIT_ID,
            vk_commitment,
        )?;
        let mut cursor = Cursor::new(proving_key_raw.as_slice());
        let pk = read_proving_key::<pasta_tiny::OfflineNoteSemantic, _>(&mut cursor)
            .map_err(|err| format!("failed to decode proving key: {err}"))?;
        let consumed = usize::try_from(cursor.position()).unwrap_or(usize::MAX);
        if consumed != proving_key_raw.len() {
            return Err("failed to decode proving key: trailing bytes".to_owned());
        }
        if halo2_backend::proving_key_domain_k(&pk) != params.k() {
            return Err("proving key domain does not match IPAK parameters".to_owned());
        }
        if halo2_backend::proving_key_vk_to_processed_bytes(&pk)
            != halo2_backend::verifying_key_to_processed_bytes(&parsed_vk)
        {
            return Err("proving key verifying key does not match vk_ref bytes".to_owned());
        }
        Arc::new(pk)
    } else {
        cached_offline_note_proving_key(&params, &parsed_vk, vk_commitment)?
    };

    let circuit = pasta_tiny::OfflineNoteSemantic {
        public_values,
        input_amounts: instance_values.input_amount_scalars(),
        output_amounts: instance_values.output_amount_scalars(),
    };
    let proof_raw = create_halo2_ipa_proof(
        &params,
        proving_key.as_ref(),
        circuit,
        &instance_refs,
        "offline-note-recursive",
    )?;

    let mut proof_payload = zk1::wrap_start();
    zk1::wrap_append_proof(&mut proof_payload, &proof_raw);
    zk1::wrap_append_instances_pasta_fp_cols(instance_columns.as_slice(), &mut proof_payload);

    let envelope = OpenVerifyEnvelope {
        backend: BackendTag::Halo2IpaPasta,
        circuit_id: circuit_id.to_owned(),
        vk_hash: vk_commitment,
        public_inputs: OFFLINE_NOTE_RECURSIVE_PUBLIC_INPUTS_SCHEMA.to_vec(),
        proof_bytes: proof_payload,
        aux: Vec::new(),
    };
    let encoded = norito::to_bytes(&envelope)
        .map_err(|err| format!("failed to encode OpenVerifyEnvelope: {err}"))?;
    Ok(ProofBox::new(ZK_BACKEND_HALO2_IPA.to_owned(), encoded))
}

/// Derive Halo2 IPA proving-key bytes for the canonical Offline recursive note circuit.
///
/// The returned bytes are a Norito archive containing the Halo2 `ProvingKey`
/// serialization, canonical circuit family, and verifier-key commitment. They
/// are intended to be generated offline and supplied to the real prover path; no
