    fn native_pasta_fp_ipa_b_vector_reduction_test_scalars()
    -> ([Scalar; 4], Vec<Scalar>, Vec<Scalar>, Scalar) {
        let initial = [
            Scalar::from(2),
            Scalar::from(5),
            Scalar::from(7),
            Scalar::from(11),
        ];
        let challenges = vec![Scalar::from(2), Scalar::from(3)];
        let inverses = challenges
            .iter()
            .map(|challenge| Option::<Scalar>::from(challenge.invert()).expect("non-zero"))
            .collect::<Vec<_>>();
        let first_layer = [
            initial[0] * inverses[0] + initial[2] * challenges[0],
            initial[1] * inverses[0] + initial[3] * challenges[0],
        ];
        let final_scalar = first_layer[0] * inverses[1] + first_layer[1] * challenges[1];
        (initial, challenges, inverses, final_scalar)
    }

    fn native_pasta_fp_ipa_transcript_binding_instances<const ROUNDS: usize>(
        circuit: &pasta_tiny::NativePastaFpIpaTranscriptBinding<ROUNDS>,
    ) -> Vec<Vec<Scalar>> {
        native_pasta_fp_ipa_transcript_binding_instances_from_values(
            circuit.header_projection,
            &circuit.round_projections,
            &circuit.challenges,
            &circuit.challenge_inverses,
            circuit.final_projection,
            circuit.binding_digest,
        )
    }

    fn native_pasta_fp_ipa_transcript_binding_instances_from_values(
        header_projection: Scalar,
        round_projections: &[Scalar],
        challenges: &[Scalar],
        challenge_inverses: &[Scalar],
        final_projection: Scalar,
        binding_digest: Scalar,
    ) -> Vec<Vec<Scalar>> {
        fn instance_at(row: usize, value: Scalar) -> Vec<Scalar> {
            let mut values = vec![Scalar::from(0); row + 1];
            values[row] = value;
            values
        }

        let rounds = round_projections.len();
        let final_row = rounds * 3;
        let mut instances = vec![
            instance_at(0, header_projection),
            instance_at(final_row, final_projection),
            instance_at(final_row, binding_digest),
        ];
        instances.extend(
            round_projections
                .iter()
                .enumerate()
                .map(|(round_index, value)| instance_at(round_index * 3, *value)),
        );
        instances.extend(
            challenges
                .iter()
                .enumerate()
                .map(|(round_index, value)| instance_at(round_index * 3 + 1, *value)),
        );
        instances.extend(
            challenge_inverses
                .iter()
                .enumerate()
                .map(|(round_index, value)| instance_at(round_index * 3 + 2, *value)),
        );
        instances
    }

    fn transcript_binding_final_instance_row<const ROUNDS: usize>() -> usize {
        ROUNDS * 3
    }

    fn transcript_binding_round_projection_instance_row(round_index: usize) -> usize {
        round_index * 3
    }

    fn transcript_binding_challenge_instance_row(round_index: usize) -> usize {
        round_index * 3 + 1
    }

    fn transcript_binding_inverse_instance_row(round_index: usize) -> usize {
        round_index * 3 + 2
    }

