    #[test]
    fn kagemusha_recursive_aggregation_proof_record_preverify_rejects_registry_mismatches() {
        let vk_box = recursive_aggregation_vk_box();
        let mut bundle = sample_recursive_aggregation_proof_bundle();
        attach_recursive_aggregation_envelope(&mut bundle, &vk_box);
        let record = recursive_aggregation_record(&vk_box);

        let mut inactive = record.clone();
        inactive.status = ConfidentialStatus::Withdrawn;
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &inactive)
                .is_err()
        );

        let mut future = record.clone();
        future.activation_height = Some(2);
        let err =
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &future)
                .expect_err("height-unbound windowed recursive aggregation record must reject");
        assert!(err.contains("chain height"), "{err}");
        assert!(
            !verify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &future),
            "height-unbound recursive aggregation verifier must reject windowed records"
        );
        let err = preverify_kagemusha_recursive_aggregation_proof_bundle_with_record_at_height(
            &bundle, &future, 1,
        )
        .expect_err("future recursive aggregation verifier record must reject");
        assert!(err.contains("not active"), "{err}");
        assert!(
            !verify_kagemusha_recursive_aggregation_proof_bundle_with_record_at_height(
                &bundle, &future, 1,
            ),
            "future recursive aggregation verifier must reject"
        );
        preverify_kagemusha_recursive_aggregation_proof_bundle_with_record_at_height(
            &bundle, &future, 2,
        )
        .expect("in-window recursive aggregation verifier record must preverify");

        let mut withdrawn_at_boundary = record.clone();
        withdrawn_at_boundary.activation_height = Some(1);
        withdrawn_at_boundary.withdraw_height = Some(1);
        let err = preverify_kagemusha_recursive_aggregation_proof_bundle_with_record_at_height(
            &bundle,
            &withdrawn_at_boundary,
            1,
        )
        .expect_err("withdrawn-at-boundary recursive aggregation record must reject");
        assert!(err.contains("not active"), "{err}");

        let mut expired = record.clone();
        expired.activation_height = Some(1);
        expired.withdraw_height = Some(2);
        let err = preverify_kagemusha_recursive_aggregation_proof_bundle_with_record_at_height(
            &bundle, &expired, 2,
        )
        .expect_err("expired recursive aggregation record must reject");
        assert!(err.contains("not active"), "{err}");

        let mut wrong_namespace = record.clone();
        wrong_namespace.namespace = "generic_confidential_transfer".to_owned();
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &wrong_namespace
            )
            .is_err()
        );

        let mut wrong_backend = record.clone();
        wrong_backend.backend = BackendTag::Stark;
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &wrong_backend
            )
            .is_err()
        );

        let mut wrong_circuit_alias = record.clone();
        wrong_circuit_alias.circuit_id = "halo2/ipa:kagemusha-recursive-aggregation-v1".to_owned();
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &wrong_circuit_alias
            )
            .is_err()
        );

        let mut wrong_schema = record.clone();
        wrong_schema.public_inputs_schema_hash = [0x11; 32];
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &wrong_schema
            )
            .is_err()
        );

        let mut zero_cap = record.clone();
        zero_cap.max_proof_bytes = 0;
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &zero_cap)
                .is_err()
        );

        let mut missing_key = record.clone();
        missing_key.key = None;
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &missing_key
            )
            .is_err()
        );

        let mut empty_key = record.clone();
        empty_key.key = Some(VerifyingKeyBox::new(
            ZK_BACKEND_HALO2_IPA.into(),
            Vec::new(),
        ));
        empty_key.vk_len = 0;
        empty_key.commitment = hash_vk(empty_key.key.as_ref().expect("empty key"));
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &empty_key)
                .is_err()
        );

        let mut wrong_len = record.clone();
        wrong_len.vk_len += 1;
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &wrong_len)
                .is_err()
        );

        let mut wrong_commitment = record.clone();
        wrong_commitment.commitment = [0x22; 32];
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &bundle,
                &wrong_commitment
            )
            .is_err()
        );

        let mut zero_commitment = record.clone();
        zero_commitment.commitment = [0u8; 32];
        let err = preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(
            &bundle,
            &zero_commitment,
        )
        .expect_err("zero recursive aggregation verifier commitment must reject");
        assert!(err.contains("commitment must be non-zero"), "{err}");

        let mut too_small = record;
        too_small.max_proof_bytes = u32::try_from(bundle.recursive_proof.proof.bytes.len() - 1)
            .expect("proof length fits u32");
        assert!(
            preverify_kagemusha_recursive_aggregation_proof_bundle_with_record(&bundle, &too_small)
                .is_err()
        );
    }

    #[derive(Clone)]
    struct OwnedFoldHop {
        root_before: [u8; 32],
        input_nullifiers: Vec<[u8; 32]>,
        output_commitments: Vec<[u8; 32]>,
        root_after: [u8; 32],
        attachment: ProofAttachment,
        vk_box: VerifyingKeyBox,
    }

    impl OwnedFoldHop {
        fn as_step(&self) -> KagemushaFoldProofStep<'_> {
            KagemushaFoldProofStep {
                root_before: self.root_before,
                input_nullifiers: &self.input_nullifiers,
                output_commitments: &self.output_commitments,
                root_after: self.root_after,
                attachment: &self.attachment,
                vk_box: &self.vk_box,
            }
        }

        fn as_bundle_step(&self) -> KagemushaVerifiedFoldStep {
            KagemushaVerifiedFoldStep {
                root_before: self.root_before,
                input_nullifiers: self.input_nullifiers.clone(),
                output_commitments: self.output_commitments.clone(),
                root_after: self.root_after,
                attachment: self.attachment.clone(),
                verifier_key: self.vk_box.clone(),
            }
        }
    }

    fn sample_generic_verified_hop(
        root_before: [u8; 32],
        root_after: [u8; 32],
        seed: u8,
    ) -> OwnedFoldHop {
        let circuit_id = "halo2/ipa:tiny-add-public";
        let fixture_seed = test_utils::halo2_fixture_envelope(circuit_id, [0u8; 32]);
        let vk_box = fixture_seed
            .vk_box(ZK_BACKEND_HALO2_IPA)
            .expect("tiny-add fixture must include a verifying key");
        let vk_commitment = hash_vk(&vk_box);
        let fixture = test_utils::halo2_fixture_envelope(circuit_id, vk_commitment);
        let mut attachment = ProofAttachment::new_ref(
            ZK_BACKEND_HALO2_IPA.into(),
            fixture.proof_box(ZK_BACKEND_HALO2_IPA),
            VerifyingKeyId::new(ZK_BACKEND_HALO2_IPA, "kagemusha-hop-fixture"),
        );
        attachment.vk_commitment = Some(vk_commitment);

        OwnedFoldHop {
            root_before,
            input_nullifiers: vec![[seed; 32]],
            output_commitments: vec![[seed.wrapping_add(1); 32]],
            root_after,
            attachment,
            vk_box,
        }
    }

    fn sample_verified_hop(root_before: [u8; 32], root_after: [u8; 32], seed: u8) -> OwnedFoldHop {
        let mut hop = sample_generic_verified_hop(root_before, root_after, seed);
        mutate_open_verify_envelope(&mut hop.attachment.proof, |envelope| {
            envelope.circuit_id = confidential_v2::CONFIDENTIAL_TRANSFER_V2_CIRCUIT_ID.to_owned();
            envelope.public_inputs =
                confidential_v2::CONFIDENTIAL_TRANSFER_V2_PUBLIC_INPUTS_SCHEMA_V1.to_vec();
        });
        hop
    }

    fn sample_confidential_v2_verified_hop()
    -> (ChainId, AssetDefinitionId, OwnedFoldHop, VerifyingKeyRecord) {
        static HOP: OnceLock<(ChainId, AssetDefinitionId, OwnedFoldHop, VerifyingKeyRecord)> =
            OnceLock::new();

        HOP.get_or_init(|| {
            let chain_id: ChainId = "kagemusha-fold-chain".parse().expect("chain id");
            let asset = AssetDefinitionId::new(
                DomainId::try_new("offline", "universal").expect("domain id"),
                "kgm".parse().expect("asset definition name"),
            );
            let record = confidential_v2::confidential_transfer_v2_vk_record(
                KAGEMUSHA_VERIFIER_NAMESPACE,
                3,
            )
            .expect("confidential transfer v2 verifier record");
            let vk_box = record.key.clone().expect("inline transfer verifier key");
            let spend_key = [0x11_u8; 32];
            let input_rho = [0x21_u8; 32];
            let input_diversifier =
                confidential_v2::derive_confidential_diversifier_v2(b"kagemusha-fold-input");
            let input_owner_tag =
                confidential_v2::derive_confidential_owner_tag_v2_with_diversifier(
                    &spend_key,
                    input_diversifier,
                )
                .expect("input owner tag");
            let input_commitment = confidential_v2::derive_confidential_note_v2(
                &asset.to_string(),
                7,
                input_rho,
                input_owner_tag,
            )
            .expect("input commitment");
            let tree_commitments = vec![input_commitment];
            let root_before = confidential_v2::compute_confidential_root_v2(&tree_commitments)
                .expect("root before");
            let output_rho = [0x31_u8; 32];
            let output_owner_tag =
                confidential_v2::derive_confidential_owner_tag_v2_with_diversifier(
                    &[0x41_u8; 32],
                    confidential_v2::derive_confidential_diversifier_v2(b"kagemusha-fold-output"),
                )
                .expect("output owner tag");
            let proof = confidential_v2::build_confidential_transfer_proof_v2(
                &chain_id,
                &asset.to_string(),
                &spend_key,
                &tree_commitments,
                &[confidential_v2::ConfidentialTransferInputV2 {
                    amount: 7,
                    rho: input_rho,
                    diversifier: input_diversifier,
                    leaf_index: 0,
                }],
                &[confidential_v2::ConfidentialTransferOutputV2 {
                    amount: 7,
                    rho: output_rho,
                    owner_tag: output_owner_tag,
                }],
                root_before,
                &record.circuit_id,
                &vk_box,
            )
            .expect("confidential transfer v2 proof");
            let mut next_tree = tree_commitments;
            next_tree.extend(proof.output_commitments.iter().copied());
            let root_after =
                confidential_v2::compute_confidential_root_v2(&next_tree).expect("root after");
            let vk_commitment = hash_vk(&vk_box);
            let mut attachment = ProofAttachment::new_ref(
                ZK_BACKEND_HALO2_IPA.into(),
                proof.proof,
                VerifyingKeyId::new(
                    ZK_BACKEND_HALO2_IPA,
                    "kagemusha-hop-confidential-transfer-v2",
                ),
            );
            attachment.vk_commitment = Some(vk_commitment);
            (
                chain_id,
                asset,
                OwnedFoldHop {
                    root_before,
                    input_nullifiers: proof.nullifiers,
                    output_commitments: proof.output_commitments,
                    root_after,
                    attachment,
                    vk_box,
                },
                record,
            )
        })
        .clone()
    }

    #[allow(clippy::too_many_arguments)]
    fn sample_confidential_v2_owned_hop_from_note(
        chain_id: &ChainId,
        asset: &AssetDefinitionId,
        record: &VerifyingKeyRecord,
        vk_box: &VerifyingKeyBox,
        tree_commitments: &[[u8; 32]],
        spend_key: [u8; 32],
        amount: u128,
        input_rho: [u8; 32],
        input_diversifier: [u8; 32],
        leaf_index: usize,
        output_rho: [u8; 32],
        output_owner_tag: [u8; 32],
    ) -> OwnedFoldHop {
        let root_before =
            confidential_v2::compute_confidential_root_v2(tree_commitments).expect("root before");
        let proof = confidential_v2::build_confidential_transfer_proof_v2(
            chain_id,
            &asset.to_string(),
            &spend_key,
            tree_commitments,
            &[confidential_v2::ConfidentialTransferInputV2 {
                amount,
                rho: input_rho,
                diversifier: input_diversifier,
                leaf_index,
            }],
            &[confidential_v2::ConfidentialTransferOutputV2 {
                amount,
                rho: output_rho,
                owner_tag: output_owner_tag,
            }],
            root_before,
            &record.circuit_id,
            vk_box,
        )
        .expect("confidential transfer v2 proof");
        let mut next_tree = tree_commitments.to_vec();
        next_tree.extend(proof.output_commitments.iter().copied());
        let root_after =
            confidential_v2::compute_confidential_root_v2(&next_tree).expect("root after");
        let vk_commitment = hash_vk(vk_box);
        let mut attachment = ProofAttachment::new_ref(
            ZK_BACKEND_HALO2_IPA.into(),
            proof.proof,
            VerifyingKeyId::new(
                ZK_BACKEND_HALO2_IPA,
                "kagemusha-hop-confidential-transfer-v2",
            ),
        );
        attachment.vk_commitment = Some(vk_commitment);
        OwnedFoldHop {
            root_before,
            input_nullifiers: proof.nullifiers,
            output_commitments: proof.output_commitments,
            root_after,
            attachment,
            vk_box: vk_box.clone(),
        }
    }

    fn sample_confidential_v2_two_hop_lineage() -> (
        ChainId,
        AssetDefinitionId,
        OwnedFoldHop,
        OwnedFoldHop,
        VerifyingKeyRecord,
    ) {
        let chain_id: ChainId = "kagemusha-recursive-spend-real-chain"
            .parse()
            .expect("chain id");
        let asset = AssetDefinitionId::new(
            DomainId::try_new("offline", "universal").expect("domain id"),
            "kgm-real-spend".parse().expect("asset definition name"),
        );
        let record =
            confidential_v2::confidential_transfer_v2_vk_record(KAGEMUSHA_VERIFIER_NAMESPACE, 3)
                .expect("confidential transfer v2 verifier record");
        let vk_box = record.key.clone().expect("inline transfer verifier key");
        let amount = 7;

        let first_spend_key = [0x11_u8; 32];
        let first_input_rho = [0x21_u8; 32];
        let first_input_diversifier =
            confidential_v2::derive_confidential_diversifier_v2(b"kagemusha-spend-hop-0-input");
        let first_input_owner_tag =
            confidential_v2::derive_confidential_owner_tag_v2_with_diversifier(
                &first_spend_key,
                first_input_diversifier,
            )
            .expect("first input owner tag");
        let first_input_commitment = confidential_v2::derive_confidential_note_v2(
            &asset.to_string(),
            amount,
            first_input_rho,
            first_input_owner_tag,
        )
        .expect("first input commitment");
        let first_tree = vec![first_input_commitment];

        let second_spend_key = [0x41_u8; 32];
        let first_output_rho = [0x31_u8; 32];
        let first_output_diversifier =
            confidential_v2::derive_confidential_diversifier_v2(b"kagemusha-spend-hop-0-output");
        let first_output_owner_tag =
            confidential_v2::derive_confidential_owner_tag_v2_with_diversifier(
                &second_spend_key,
                first_output_diversifier,
            )
            .expect("first output owner tag");
        let first_hop = sample_confidential_v2_owned_hop_from_note(
            &chain_id,
            &asset,
            &record,
            &vk_box,
            &first_tree,
            first_spend_key,
            amount,
            first_input_rho,
            first_input_diversifier,
            0,
            first_output_rho,
            first_output_owner_tag,
        );

        let mut second_tree = first_tree;
        second_tree.extend(first_hop.output_commitments.iter().copied());
        let final_spend_key = [0x51_u8; 32];
        let second_output_rho = [0x61_u8; 32];
        let second_output_diversifier =
            confidential_v2::derive_confidential_diversifier_v2(b"kagemusha-spend-hop-1-output");
        let second_output_owner_tag =
            confidential_v2::derive_confidential_owner_tag_v2_with_diversifier(
                &final_spend_key,
                second_output_diversifier,
            )
            .expect("second output owner tag");
        let second_hop = sample_confidential_v2_owned_hop_from_note(
            &chain_id,
            &asset,
            &record,
            &vk_box,
            &second_tree,
            second_spend_key,
            amount,
            first_output_rho,
            first_output_diversifier,
            1,
            second_output_rho,
            second_output_owner_tag,
        );

        (chain_id, asset, first_hop, second_hop, record)
    }

