    #[test]
    #[ignore = "heavy Kagemusha Halo2 IPA proof generation; run explicitly with --ignored --test-threads=1"]
    fn kagemusha_compact_payment_token_record_verifier_rejects_registry_mismatches() {
        let record =
            kagemusha_folded_vk_record(KAGEMUSHA_VERIFIER_NAMESPACE, 3).expect("vk record");
        let vk_box = record.key.as_ref().expect("inline verifier key");
        let token = prove_kagemusha_compact_payment_token(
            &record.circuit_id,
            vk_box,
            sample_public_inputs(),
            None,
        )
        .expect("real Kagemusha folded proof");

        let mut inactive = record.clone();
        inactive.status = ConfidentialStatus::Withdrawn;
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token, &inactive
        ));

        let mut wrong_namespace = record.clone();
        wrong_namespace.namespace = "generic_confidential_transfer".to_owned();
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &wrong_namespace
        ));

        let mut wrong_curve = record.clone();
        wrong_curve.curve = "pasta".to_owned();
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &wrong_curve
        ));

        let mut wrong_circuit_alias = record.clone();
        wrong_circuit_alias.circuit_id = "halo2/ipa:kagemusha-folded-v1".to_owned();
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &wrong_circuit_alias
        ));

        let mut wrong_schema = record.clone();
        wrong_schema.public_inputs_schema_hash = [0x11; 32];
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &wrong_schema
        ));

        let mut missing_key = record.clone();
        missing_key.key = None;
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &missing_key
        ));

        let mut wrong_commitment = record.clone();
        wrong_commitment.commitment = [0x22; 32];
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &wrong_commitment
        ));

        let mut zero_commitment = record.clone();
        zero_commitment.commitment = [0u8; 32];
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token,
            &zero_commitment
        ));

        let mut too_small = record;
        too_small.max_proof_bytes =
            u32::try_from(token.folded_proof.proof.bytes.len() - 1).expect("proof length fits u32");
        assert!(!verify_kagemusha_compact_payment_token_with_record(
            &token, &too_small
        ));
    }

