    #[test]
    fn kagemusha_verified_recursive_aggregation_evidence_from_records_accepts_active_records() {
        let (chain_id, asset, hop, record) = sample_confidential_v2_verified_hop();
        let bundle = KagemushaVerifiedFoldBundle {
            chain_id,
            asset,
            steps: vec![hop.as_bundle_step()],
        };
        let id = hop.attachment.vk_ref.clone();
        let records = [KagemushaHopVerifierRecord {
            id: &id,
            record: &record,
        }];
        let opening_len = 4;
        let params_fingerprint = fixed_bytes(b"kagemusha-recursive-core-params");
        let schedule_digest =
            kagemusha_recursive_fixed_window_table_schedule_digest(opening_len as usize)
                .expect("canonical recursive schedule digest");
        let manifest_digest =
            kagemusha_recursive_fixed_window_shared_table_manifest_digest(opening_len as usize)
                .expect("canonical recursive shared-table manifest digest");
        let base_digest = fixed_bytes(b"kagemusha-recursive-core-bases");
        let batch_digest = fixed_bytes(b"kagemusha-recursive-core-batch");

        let evidence = kagemusha_verified_recursive_aggregation_evidence_from_bundle_with_records(
            &bundle,
            &records,
            1,
            opening_len,
            params_fingerprint,
            schedule_digest,
            manifest_digest,
            base_digest,
            batch_digest,
        )
        .expect("record-backed recursive aggregation evidence");
        assert_eq!(
            evidence.aggregation_statement.aggregation_mode,
            iroha_data_model::offline::KAGEMUSHA_AGGREGATION_MODE_RECURSIVE_IN_CIRCUIT_V1
        );
        assert_eq!(evidence.verifier_witness_count, 1);
        assert_eq!(
            evidence.verifier_witness_profile,
            KAGEMUSHA_RECURSIVE_VERIFIER_WITNESS_PROFILE_V1
        );
        assert_eq!(evidence.verifier_opening_len, opening_len);
        assert_eq!(evidence.verifier_params_fingerprint, params_fingerprint);
        assert_eq!(evidence.fixed_window_table_schedule_digest, schedule_digest);
        assert_eq!(
            evidence.fixed_window_shared_table_manifest_digest,
            manifest_digest
        );
        assert_eq!(evidence.fixed_window_table_base_digest, base_digest);
        assert_eq!(evidence.verifier_witness_batch_digest, batch_digest);
        assert_eq!(evidence.aggregation_statement.initial_root, hop.root_before);
        assert_eq!(evidence.aggregation_statement.final_root, hop.root_after);
        let recursive_projection =
            iroha_data_model::offline::kagemusha_folded_public_inputs_from_aggregation_statement(
                &evidence.aggregation_statement,
            )
            .expect("recursive aggregation transcript projection");
        assert_eq!(
            recursive_projection.aggregation_mode,
            iroha_data_model::offline::KAGEMUSHA_AGGREGATION_MODE_RECURSIVE_IN_CIRCUIT_V1
        );
        assert!(matches!(
            recursive_projection.validate_supported_context(),
            Err(iroha_data_model::offline::KagemushaFoldError::UnsupportedAggregationMode {
                actual,
                ..
            }) if actual == iroha_data_model::offline::KAGEMUSHA_AGGREGATION_MODE_RECURSIVE_IN_CIRCUIT_V1
        ));
        let evidence_digest =
            iroha_data_model::offline::kagemusha_recursive_aggregation_evidence_digest(&evidence)
                .expect("recursive aggregation evidence digest");
        assert_ne!(evidence_digest, [0u8; 32]);

        let record_bundle = KagemushaVerifiedFoldRecordBundle {
            bundle: bundle.clone(),
            verifier_records: vec![KagemushaVerifiedFoldVerifierRecord {
                id: id.clone(),
                record: record.clone(),
            }],
        };
        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle(
                &record_bundle,
                1,
                opening_len,
                params_fingerprint,
                schedule_digest,
                manifest_digest,
                base_digest,
                batch_digest,
            )
            .expect("serializable record-backed recursive aggregation evidence")
        );
    }

    #[test]
    fn kagemusha_verified_recursive_aggregation_evidence_from_pallas_batch_accepts_active_records()
    {
        let (chain_id, asset, hop, record) = sample_confidential_v2_verified_hop();
        let bundle = KagemushaVerifiedFoldBundle {
            chain_id,
            asset,
            steps: vec![hop.as_bundle_step()],
        };
        let id = hop.attachment.vk_ref.clone();
        let records = [KagemushaHopVerifierRecord {
            id: &id,
            record: &record,
        }];
        let (params, witness) =
            super::kagemusha_non_native_limb_circuit_tests::sample_pallas_verifier_witness(
                4,
                "core-recursive-record-backed-pallas",
            );
        let witnesses = vec![witness];
        let preflight = kagemusha_pallas_ipa_batch_verifier_preflight(&params, &witnesses)
            .expect("Pallas verifier witness batch preflight");
        let hop_proof_hash =
            kagemusha_fold_step_proof_hash(&hop.attachment.proof).expect("hop proof hash");
        let hop_bound_preflight =
            kagemusha_pallas_ipa_batch_verifier_preflight_bound_to_hop_proofs(
                &params,
                &witnesses,
                &[hop_proof_hash],
            )
            .expect("hop-bound Pallas verifier witness batch preflight");
        assert_ne!(
            preflight.aggregate_digest, hop_bound_preflight.aggregate_digest,
            "hop-bound preflight digest must not equal the detached native batch digest"
        );
        assert_eq!(
            preflight.fixed_window_table_schedule_digest,
            hop_bound_preflight.fixed_window_table_schedule_digest,
            "hop proof binding must not rewrite the deterministic table schedule"
        );
        assert_eq!(
            preflight.fixed_window_shared_table_manifest_digest,
            hop_bound_preflight.fixed_window_shared_table_manifest_digest,
            "hop proof binding must not rewrite the deterministic shared-table manifest"
        );
        assert_eq!(
            preflight.fixed_window_table_base_digest,
            hop_bound_preflight.fixed_window_table_base_digest,
            "hop proof binding must not rewrite the actual verifier table bases"
        );
        let forged_hop_bound = kagemusha_pallas_ipa_batch_verifier_preflight_bound_to_hop_proofs(
            &params,
            &witnesses,
            &[Hash::new(b"forged-kagemusha-hop-proof-hash")],
        )
        .expect("forged hop-bound Pallas verifier witness batch preflight");
        assert_ne!(
            hop_bound_preflight.aggregate_digest, forged_hop_bound.aggregate_digest,
            "hop-bound preflight digest must change when the ordered hop proof hash changes"
        );
        assert_eq!(
            hop_bound_preflight.fixed_window_table_schedule_digest,
            forged_hop_bound.fixed_window_table_schedule_digest,
            "forged hop hash must not change the deterministic table schedule"
        );
        assert_eq!(
            hop_bound_preflight.fixed_window_shared_table_manifest_digest,
            forged_hop_bound.fixed_window_shared_table_manifest_digest,
            "forged hop hash must not change the shared-table manifest"
        );
        assert_eq!(
            hop_bound_preflight.fixed_window_table_base_digest,
            forged_hop_bound.fixed_window_table_base_digest,
            "forged hop hash must not change the verifier table bases"
        );

        let evidence =
            kagemusha_verified_recursive_aggregation_evidence_from_bundle_with_records_and_pallas_batch(
                &bundle,
                &records,
                &params,
                &witnesses,
            )
            .expect("record-backed recursive aggregation evidence from Pallas batch");
        assert_eq!(
            evidence.verifier_witness_count as usize,
            preflight.proof_count
        );
        assert_eq!(
            evidence.verifier_witness_profile,
            preflight.verifier_witness_profile
        );
        assert_eq!(evidence.verifier_opening_len, preflight.opening_len);
        assert_eq!(
            evidence.verifier_params_fingerprint,
            preflight.params_fingerprint
        );
        assert_eq!(
            evidence.fixed_window_table_schedule_digest,
            preflight.fixed_window_table_schedule_digest
        );
        assert_eq!(
            evidence.fixed_window_shared_table_manifest_digest,
            preflight.fixed_window_shared_table_manifest_digest
        );
        assert_eq!(
            evidence.fixed_window_table_base_digest,
            preflight.fixed_window_table_base_digest
        );
        assert_eq!(
            evidence.verifier_witness_batch_digest,
            hop_bound_preflight.aggregate_digest
        );
        validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &hop_bound_preflight,
        )
        .expect("record-backed LEN=4 evidence binds to one-hop verifier-slice metadata");
        let mut digest_splice = hop_bound_preflight;
        digest_splice.aggregate_digest[0] ^= 1;
        let digest_err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &digest_splice,
        )
        .err()
        .expect("one-hop verifier-slice evidence binding must reject batch digest splice");
        assert!(
            digest_err.contains("verifier-witness batch digest mismatch"),
            "expected verifier-witness batch digest mismatch, found {digest_err:?}"
        );
        let mut proof_count_splice = hop_bound_preflight;
        proof_count_splice.proof_count = 2;
        let proof_count_err =
            validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
                &evidence,
                &proof_count_splice,
            )
            .err()
            .expect("one-hop verifier-slice evidence binding must reject proof-count splice");
        assert!(
            proof_count_err.contains("requires one preflight witness"),
            "expected one preflight witness rejection, found {proof_count_err:?}"
        );
        let mut profile_splice = hop_bound_preflight;
        profile_splice.verifier_witness_profile = "forged-kagemusha-witness-profile";
        let profile_err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &profile_splice,
        )
        .err()
        .expect("one-hop verifier-slice evidence binding must reject witness-profile splice");
        assert!(
            profile_err.contains("verifier-witness profile mismatch"),
            "expected verifier-witness profile mismatch, found {profile_err:?}"
        );
        let mut params_splice = hop_bound_preflight;
        params_splice.params_fingerprint[0] ^= 1;
        let params_err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &params_splice,
        )
        .err()
        .expect("one-hop verifier-slice evidence binding must reject params fingerprint splice");
        assert!(
            params_err.contains("verifier parameter fingerprint mismatch"),
            "expected params fingerprint mismatch, found {params_err:?}"
        );
        let mut schedule_splice = hop_bound_preflight;
        schedule_splice.fixed_window_table_schedule_digest[0] ^= 1;
        let schedule_err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &schedule_splice,
        )
        .err()
        .expect("one-hop verifier-slice evidence binding must reject schedule digest splice");
        assert!(
            schedule_err.contains("fixed-window schedule digest mismatch"),
            "expected fixed-window schedule mismatch, found {schedule_err:?}"
        );
        let mut shared_manifest_splice = hop_bound_preflight;
        shared_manifest_splice.fixed_window_shared_table_manifest_digest[0] ^= 1;
        let shared_manifest_err =
            validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
                &evidence,
                &shared_manifest_splice,
            )
            .err()
            .expect(
                "one-hop verifier-slice evidence binding must reject shared-table manifest splice",
            );
        assert!(
            shared_manifest_err.contains("shared-table manifest digest mismatch"),
            "expected shared-table manifest mismatch, found {shared_manifest_err:?}"
        );
        let mut opening_len_splice = hop_bound_preflight;
        opening_len_splice.opening_len = 2;
        let opening_len_err =
            validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
                &evidence,
                &opening_len_splice,
            )
            .err()
            .expect("one-hop verifier-slice evidence binding must reject opening-length splice");
        assert!(
            opening_len_err.contains("opening length 2"),
            "expected LEN=2 profile rejection, found {opening_len_err:?}"
        );
        assert_eq!(evidence.aggregation_statement.initial_root, hop.root_before);
        assert_eq!(evidence.aggregation_statement.final_root, hop.root_after);

        let record_bundle = KagemushaVerifiedFoldRecordBundle {
            bundle: bundle.clone(),
            verifier_records: vec![KagemushaVerifiedFoldVerifierRecord {
                id: id.clone(),
                record: record.clone(),
            }],
        };
        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_batch(
                &record_bundle,
                &params,
                &witnesses,
            )
            .expect("serializable record-backed recursive evidence from Pallas batch")
        );
    }

    #[test]
    fn kagemusha_verified_recursive_aggregation_evidence_from_pallas_open_envelopes_accepts_active_records()
     {
        let (chain_id, asset, hop, record) = sample_confidential_v2_verified_hop();
        let bundle = KagemushaVerifiedFoldBundle {
            chain_id,
            asset,
            steps: vec![hop.as_bundle_step()],
        };
        let id = hop.attachment.vk_ref.clone();
        let records = [KagemushaHopVerifierRecord {
            id: &id,
            record: &record,
        }];
        let metadata = kagemusha_pallas_open_envelope_metadata_for_verified_hop(
            &bundle.chain_id,
            &bundle.asset,
            0,
            &bundle.steps[0],
        )
        .expect("Pallas open-envelope hop metadata");
        assert_eq!(metadata.vk_commitment, Some(hash_vk(&hop.vk_box)));
        assert_eq!(
            metadata.public_inputs_schema_hash,
            Some(kagemusha_confidential_v2_public_inputs_schema_hash())
        );
        assert_ne!(metadata.domain_tag, Some([0u8; 32]));
        let envelope =
            super::kagemusha_non_native_limb_circuit_tests::sample_pallas_open_envelope_with_metadata(
                4,
                "core-recursive-record-backed-pallas-open-envelope",
                metadata,
            );
        let hop_proof_hash =
            kagemusha_fold_step_proof_hash(&hop.attachment.proof).expect("hop proof hash");
        let preflight =
            kagemusha_pallas_ipa_batch_verifier_preflight_from_open_envelopes_bound_to_hop_proofs(
                std::slice::from_ref(&envelope),
                &[hop_proof_hash],
            )
            .expect("proof-derived open-envelope preflight binds to hop proof hash");

        let evidence =
            kagemusha_verified_recursive_aggregation_evidence_from_bundle_with_records_and_pallas_open_envelopes(
                &bundle,
                &records,
                std::slice::from_ref(&envelope),
            )
            .expect("record-backed recursive aggregation evidence from Pallas open envelope");
        assert_eq!(evidence.verifier_witness_count, 1);
        assert_eq!(evidence.verifier_opening_len, preflight.opening_len);
        assert_eq!(
            evidence.verifier_params_fingerprint,
            preflight.params_fingerprint
        );
        assert_eq!(
            evidence.fixed_window_table_schedule_digest,
            preflight.fixed_window_table_schedule_digest
        );
        assert_eq!(
            evidence.fixed_window_shared_table_manifest_digest,
            preflight.fixed_window_shared_table_manifest_digest
        );
        assert_eq!(
            evidence.fixed_window_table_base_digest,
            preflight.fixed_window_table_base_digest
        );
        assert_eq!(
            evidence.verifier_witness_batch_digest,
            preflight.aggregate_digest
        );
        validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence, &preflight,
        )
        .expect(
            "record-backed open-envelope LEN=4 evidence binds to one-hop verifier-slice metadata",
        );
        let mut table_base_splice = preflight;
        table_base_splice.fixed_window_table_base_digest[0] ^= 1;
        let err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &table_base_splice,
        )
        .err()
        .expect("one-hop verifier-slice evidence binding must reject table-base splice");
        assert!(
            err.contains("fixed-window table-base digest mismatch"),
            "expected table-base digest mismatch, found {err:?}"
        );
        let mut params_splice = preflight;
        params_splice.params_fingerprint[0] ^= 1;
        let err = validate_kagemusha_recursive_one_hop_verifier_slice_preflight_binding(
            &evidence,
            &params_splice,
        )
        .err()
        .expect("one-hop verifier-slice open-envelope evidence must reject params splice");
        assert!(
            err.contains("verifier parameter fingerprint mismatch"),
            "expected open-envelope params mismatch, found {err:?}"
        );

        let record_bundle = KagemushaVerifiedFoldRecordBundle {
            bundle: bundle.clone(),
            verifier_records: vec![KagemushaVerifiedFoldVerifierRecord {
                id: id.clone(),
                record: record.clone(),
            }],
        };
        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelopes(
                &record_bundle,
                &[envelope.clone()],
            )
            .expect("serializable record-backed recursive evidence from Pallas open envelope")
        );
        let envelope_archive =
            norito::to_bytes(&vec![envelope.clone()]).expect("encode Pallas open-envelope archive");
        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelope_archive(
                &record_bundle,
                &envelope_archive,
            )
            .expect("archive-backed record-backed recursive evidence from Pallas open envelope")
        );

        let mut windowed_record = record.clone();
        windowed_record.activation_height = Some(2);
        windowed_record.withdraw_height = Some(4);
        let windowed_record_bundle = KagemushaVerifiedFoldRecordBundle {
            bundle,
            verifier_records: vec![KagemushaVerifiedFoldVerifierRecord {
                id,
                record: windowed_record,
            }],
        };
        let err =
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelopes(
                &windowed_record_bundle,
                std::slice::from_ref(&envelope),
            )
            .expect_err("height-unbound recursive evidence must reject windowed records");
        assert!(err.contains("chain height"), "{err}");

        let err =
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelopes_at_height(
                &windowed_record_bundle,
                std::slice::from_ref(&envelope),
                1,
            )
            .expect_err("future recursive evidence verifier record must reject");
        assert!(err.contains("not active"), "{err}");

        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelopes_at_height(
                &windowed_record_bundle,
                std::slice::from_ref(&envelope),
                2,
            )
            .expect("in-window recursive evidence verifier record must pass")
        );
        assert_eq!(
            evidence,
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelope_archive_at_height(
                &windowed_record_bundle,
                &envelope_archive,
                2,
            )
            .expect("in-window archived recursive evidence verifier record must pass")
        );

        let err =
            kagemusha_verified_recursive_aggregation_evidence_from_record_bundle_and_pallas_open_envelopes_at_height(
                &windowed_record_bundle,
                std::slice::from_ref(&envelope),
                4,
            )
            .expect_err("withdrawn recursive evidence verifier record must reject");
        assert!(err.contains("not active"), "{err}");
    }

    #[test]
    #[ignore = "heavy Kagemusha Halo2 IPA proof generation; run explicitly with --ignored --test-threads=1"]
    fn prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_pallas_batch_accepts_active_records()
     {
        let (chain_id, asset, hop, record) = sample_confidential_v2_verified_hop();
        let bundle = KagemushaVerifiedFoldBundle {
            chain_id,
            asset,
            steps: vec![hop.as_bundle_step()],
        };
        let id = hop.attachment.vk_ref.clone();
        let records = [KagemushaHopVerifierRecord {
            id: &id,
            record: &record,
        }];
        let (params, witness) =
            super::kagemusha_non_native_limb_circuit_tests::sample_pallas_verifier_witness(
                4,
                "core-recursive-proof-bundle-pallas-batch",
            );
        let witnesses = vec![witness];
        let recursive_vk = recursive_aggregation_vk_box();
        let recursive_record = recursive_aggregation_record(&recursive_vk);
        let proof_bundle =
            prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_bundle_with_records_and_pallas_batch(
                &bundle,
                &records,
                &params,
                &witnesses,
                KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
                &recursive_vk,
                None,
            )
            .expect("record-backed recursive aggregation proof bundle from Pallas batch");
        let evidence =
            kagemusha_verified_recursive_aggregation_evidence_from_bundle_with_records_and_pallas_batch(
                &bundle,
                &records,
                &params,
                &witnesses,
            )
            .expect("record-backed recursive aggregation evidence from Pallas batch");
        assert_eq!(proof_bundle.evidence, evidence);
        proof_bundle
            .validate_evidence_binding()
            .expect("recursive proof bundle binds derived evidence");
        preverify_kagemusha_recursive_aggregation_proof_bundle(&proof_bundle, &recursive_vk)
            .expect("recursive proof bundle preverification");
        assert!(verify_kagemusha_recursive_aggregation_proof_bundle(
            &proof_bundle,
            &recursive_vk
        ));
        assert!(
            verify_kagemusha_recursive_aggregation_proof_bundle_with_record(
                &proof_bundle,
                &recursive_record
            )
        );

        let record_bundle = KagemushaVerifiedFoldRecordBundle {
            bundle: bundle.clone(),
            verifier_records: vec![KagemushaVerifiedFoldVerifierRecord {
                id: id.clone(),
                record: record.clone(),
            }],
        };
        let record_proof_bundle =
            prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_record_bundle_and_pallas_batch(
                &record_bundle,
                &params,
                &witnesses,
                KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
                &recursive_vk,
                None,
            )
            .expect("serializable record-backed recursive proof bundle from Pallas batch");
        assert_eq!(record_proof_bundle.evidence, proof_bundle.evidence);
        assert_eq!(
            record_proof_bundle.recursive_proof.public_inputs,
            proof_bundle.recursive_proof.public_inputs
        );
        assert!(verify_kagemusha_recursive_aggregation_proof_bundle(
            &record_proof_bundle,
            &recursive_vk
        ));
    }

    #[test]
    fn prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_pallas_batch_rejects_adversarial_inputs()
     {
        let (chain_id, asset, mut hop, record) = sample_confidential_v2_verified_hop();
        let bundle = KagemushaVerifiedFoldBundle {
            chain_id: chain_id.clone(),
            asset: asset.clone(),
            steps: vec![hop.as_bundle_step()],
        };
        let id = hop.attachment.vk_ref.clone();
        let records = [KagemushaHopVerifierRecord {
            id: &id,
            record: &record,
        }];
        let (params, witness) =
            super::kagemusha_non_native_limb_circuit_tests::sample_pallas_verifier_witness(
                4,
                "core-recursive-proof-bundle-pallas-reject",
            );
        let recursive_vk = recursive_aggregation_vk_box();
        let folded_vk = kagemusha_vk_box();

        let err =
            prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_bundle_with_records_and_pallas_batch(
                &bundle,
                &records,
                &params,
                std::slice::from_ref(&witness),
                KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
                &folded_vk,
                None,
            )
            .expect_err("folded verifier key must not prove recursive aggregation bundle");
        assert!(
            err.contains("canonical semantic circuit key"),
            "unexpected folded-vk error: {err}"
        );

        let mut spliced = witness.clone();
        spliced.accumulation.final_q = spliced.accumulation.initial_q;
        let err =
            prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_bundle_with_records_and_pallas_batch(
                &bundle,
                &records,
                &params,
                &[spliced],
                KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
                &recursive_vk,
                None,
            )
            .expect_err("tampered Pallas witness must reject before recursive proof generation");
        assert!(
            err.contains("batch witness 0 failed preflight"),
            "unexpected Pallas preflight error: {err}"
        );
        assert!(
            err.contains("accumulator final Q mismatch"),
            "unexpected Pallas accumulator error: {err}"
        );

        hop.attachment.proof.bytes = vec![0xA7];
        let tampered_bundle = KagemushaVerifiedFoldBundle {
            chain_id,
            asset,
            steps: vec![hop.as_bundle_step()],
        };
        let err =
            prove_verified_kagemusha_recursive_aggregation_proof_bundle_from_bundle_with_records_and_pallas_batch(
                &tampered_bundle,
                &records,
                &params,
                &[witness],
                KAGEMUSHA_RECURSIVE_AGGREGATION_CIRCUIT_ID,
                &recursive_vk,
                None,
            )
            .expect_err("tampered hop proof must reject before recursive proof generation");
        assert!(
            err.contains("not a valid OpenVerifyEnvelope") || err.contains("verification failed"),
            "unexpected tampered-hop error: {err}"
        );
    }

