                    crate::zk::assign_advice_compat(
                        &mut region,
                        || "m",
                        m,
                        0,
                        || Value::known(Scalar::from(11)),
                    )?;
                    crate::zk::assign_advice_compat(
                        &mut region,
                        || "r",
                        r,
                        0,
                        || Value::known(Scalar::from(31)),
                    )?;
