                // commit = H(v,rho)
                let a = vq + halo2_proofs::plonk::Expression::Constant(Scalar::from(7));
                let b = rhoq + halo2_proofs::plonk::Expression::Constant(Scalar::from(13));
                let a2 = a.clone() * a.clone();
